106.     private void InitializePlayers()
107.     {
108.         foreach (var clientId in NetworkManager.Singleton.ConnectedClientsIds)
109.         {
110.             PlayerScores.Add(new PlayerScoreInfo { ClientId = clientId, Score = 0 });
111.             Debug.Log($"[QuizGame] Thêm Player {clientId} vào bảng điểm.");
112.         }
113.     }
114.     private void StartNextQuestion()
115.     {
116.         if (CurrentQuestionNumber.Value > maxQuestions || questionPool.Count == 0)
117.         {
118.             EndGame();
119.             return;
120.         }
121.         int randomIndex = UnityEngine.Random.Range(0, questionPool.Count);
122.         CurrentQuestion.Value = questionPool[randomIndex];
123.         questionPool.RemoveAt(randomIndex);
124.         TimeRemaining.Value = timePerQuestion;
125.         AnsweringClientId.Value = 9999;
126.         AnswerTimeRemaining.Value = 0;
127.         wrongThisRound.Clear(); 
128.         NewRoundClientRpc();
129.         Debug.Log($"[QuizGame] === Câu {CurrentQuestionNumber.Value}: {CurrentQuestion.Value.QuestionText} ===");
130.     }
131.     [ClientRpc]
132.     private void NewRoundClientRpc()
133.     {
134.     }
135.     private void Update()
136.     {
137.         if (!IsServer) return;
138.         if (AnsweringClientId.Value == 9999)
139.         {
140.             TimeRemaining.Value -= Time.deltaTime;
141.             if (TimeRemaining.Value <= 0)
142.             {
143.                 CurrentQuestionNumber.Value++;
144.                 StartNextQuestion();
145.             }
146.         }
147.         else
148.         {
149.             AnswerTimeRemaining.Value -= Time.deltaTime;
150.             if (AnswerTimeRemaining.Value <= 0)
151.             {
152.                 Debug.Log($"[QuizGame] Player {AnsweringClientId.Value} hết 3s, coi như sai!");
153.                 HandleWrongAnswer(AnsweringClientId.Value);
154.             }
155.         }
156.     }
157.     private void HandleWrongAnswer(ulong clientId)
158.     {
159.         wrongThisRound.Add(clientId);
160.         AnsweringClientId.Value = 9999;
161.         NotifyWrongClientRpc(clientId);
162.     }
163.     [ClientRpc]
164.     private void NotifyWrongClientRpc(ulong wrongClientId)
165.     {
166.     }
167.     [HideInInspector] public bool localPlayerWrongThisRound = false;
168.     [ServerRpc(RequireOwnership = false)]
169.     public void SubmitHandServerRpc(ServerRpcParams rpcParams = default)
170.     {
171.         ulong clientId = rpcParams.Receive.SenderClientId;
172.         if (AnsweringClientId.Value == 9999 && !wrongThisRound.Contains(clientId))
173.         {
174.             AnsweringClientId.Value = clientId;
175.             AnswerTimeRemaining.Value = timeToAnswer;
176.             Debug.Log($"[QuizGame] Player {clientId} giơ tay!");
177.         }
178.     }
179.     [ServerRpc(RequireOwnership = false)]
180.     public void SubmitAnswerServerRpc(int answerIndex, ServerRpcParams rpcParams = default)
181.     {
182.         ulong clientId = rpcParams.Receive.SenderClientId;
183.         if (AnsweringClientId.Value != clientId) return;
184.         int pIndex = GetPlayerIndex(clientId);
185.         if (pIndex < 0) return;
186.         if (answerIndex == CurrentQuestion.Value.CorrectIndex)
187.         {
188.             var p = PlayerScores[pIndex];
189.             p.Score += 1;
190.             PlayerScores[pIndex] = p;
191.             Debug.Log($"[QuizGame] Player {clientId} ĐÚNG! Score = {p.Score}");
192.             BroadcastScores();
193.             AnsweringClientId.Value = 9999;
194.             Invoke(nameof(GoToNextQuestion), 0.5f);
195.         }
196.         else
197.         {
198.             Debug.Log($"[QuizGame] Player {clientId} SAI!");
199.             HandleWrongAnswer(clientId);
200.         }
201.     }
202.     private void GoToNextQuestion()
203.     {
204.         CurrentQuestionNumber.Value++;
205.         StartNextQuestion();
206.     }
207.     private int GetPlayerIndex(ulong clientId)
208.     {
209.         for (int i = 0; i < PlayerScores.Count; i++)
210.         {
211.             if (PlayerScores[i].ClientId == clientId) return i;
212.         }
213.         return -1;
214.     }
215.     public static string LatestRankingText = "Dang cho...";
216.     public void BroadcastScores()
217.     {
218.         string text = "BANG DIEM\n";
219.         for (int i = 0; i < PlayerScores.Count; i++)
220.         {
221.             var s = PlayerScores[i];
222.             string name = GetPlayerName(s.ClientId);
223.             text += name + ": " + s.Score + " diem\n";
224.         }
225.         Debug.Log("[QuizGame] Broadcasting: " + text);
226.         UpdateScoresClientRpc(text);
227.     }
228.     [ClientRpc]
229.     private void UpdateScoresClientRpc(string rankingText)
230.     {
231.         LatestRankingText = rankingText;
232.         Debug.Log("[QuizGame CLIENT] Nhan ranking: " + rankingText);
233.     }
234.     private void EndGame()
235.     {
236.         FinalScores.Clear();
237.         foreach (var s in PlayerScores)
238.         {
239.             FinalScores.Add(s);
240.         }
241.         NetworkManager.Singleton.SceneManager.LoadScene(endSceneName, UnityEngine.SceneManagement.LoadSceneMode.Single);
242.     }
243. }
