1. ﻿// Program.cs
2. using Fleck;
3. using System.Text.Json;
4. 
5. var rooms = new Dictionary<string, Room>();
6. var connectionToPlayer = new Dictionary<IWebSocketConnection, PlayerInfo>();
7. 
8. var server = new WebSocketServer("ws://0.0.0.0:8181");
9. 
10. server.Start(socket =>
11. {
12.     socket.OnOpen = () => Console.WriteLine("Client connected");
13. 
14.     socket.OnMessage = message =>
15.     {
16.         var msg = JsonSerializer.Deserialize<ClientMessage>(message);
17.         switch (msg?.Type)
18.         {
19.             case "CREATE_ROOM":
20.                 HandleCreateRoom(socket, msg.PlayerName);
21.                 break;
22.             case "JOIN_ROOM":
23.                 HandleJoinRoom(socket, msg.RoomId, msg.PlayerName);
24.                 break;
25.             case "LEAVE_ROOM":
26.                 HandleLeaveRoom(socket);
27.                 break;
28.         }
29.     };
30. 
31.     socket.OnClose = () => HandleLeaveRoom(socket);
32. });
33. 
34. Console.WriteLine("Server chạy tại ws://localhost:8181");
35. Console.ReadLine();
36. 
37. // ─── Handlers ───
38. 
39. void HandleCreateRoom(IWebSocketConnection socket, string playerName)
40. {
41.     var roomId = Guid.NewGuid().ToString()[..6].ToUpper();
42.     var player = new PlayerInfo { Name = playerName, IsHost = true };
43.     var room = new Room
44.     {
45.         RoomId = roomId,
46.         Host = socket,
47.         Players = new() { { socket, player } }
48.     };
49.     rooms[roomId] = room;
50.     connectionToPlayer[socket] = player;
51. 
52.     BroadcastRoomState(room);
53. }
54. 
55. void HandleJoinRoom(IWebSocketConnection socket, string roomId, string playerName)
56. {
57.     if (!rooms.TryGetValue(roomId, out var room))
58.     {
59.         socket.Send(JsonSerializer.Serialize(new
60.         {
61.             Type = "ERROR",
62.             Message = "Phòng không tồn tại!"
63.         }));
64.         return;
65.     }
66. 
67.     if (room.Players.Count >= 4)
68.     {
69.         socket.Send(JsonSerializer.Serialize(new
70.         {
71.             Type = "ERROR",
72.             Message = "Phòng đã đầy!"
73.         }));
74.         return;
75.     }
76. 
77.     var player = new PlayerInfo { Name = playerName, IsHost = false };
78.     room.Players[socket] = player;
79.     connectionToPlayer[socket] = player;
80. 
81.     BroadcastRoomState(room);
82. }
83. 
84. void HandleLeaveRoom(IWebSocketConnection socket)
85. {
86.     foreach (var (roomId, room) in rooms)
87.     {
88.         if (room.Players.Remove(socket))
89.         {
90.             connectionToPlayer.Remove(socket);
91.             if (room.Players.Count == 0)
92.             {
93.                 rooms.Remove(roomId);
94.             }
95.             else
96.             {
97.                 // Chuyển host nếu host rời
98.                 if (room.Host == socket)
99.                 {
100.                     var newHost = room.Players.First();
101.                     room.Host = newHost.Key;
102.                     newHost.Value.IsHost = true;
103.                 }
104.                 BroadcastRoomState(room);
105.             }
106.             break;
107.         }
108.     }
109. }
110. 
111. void BroadcastRoomState(Room room)
112. {
113.     var state = new
114.     {
115.         Type = "ROOM_STATE",
116.         RoomId = room.RoomId,
117.         Players = room.Players.Values.Select(p => new
