    private Task SendMessageAsync(PlayerSession session, NetworkMessage message)
    {
        var payload = JsonSerializer.SerializeToUtf8Bytes(message, _jsonOptions);
        var header = BitConverter.GetBytes(payload.Length);
        var buffer = new byte[header.Length + payload.Length];
        Buffer.BlockCopy(header, 0, buffer, 0, header.Length);
        Buffer.BlockCopy(payload, 0, buffer, header.Length, payload.Length);

        return session.Stream.WriteAsync(buffer).AsTask();
    }

    private async Task<NetworkMessage?> ReadMessageAsync(NetworkStream stream)
    {
        var lengthBuffer = new byte[4];
        var read = 0;
        while (read < lengthBuffer.Length)
        {
            var bytesRead = await stream.ReadAsync(lengthBuffer.AsMemory(read, lengthBuffer.Length - read)).ConfigureAwait(false);
            if (bytesRead == 0)
            {
                return null;
            }
            read += bytesRead;
        }

        var payloadLength = BitConverter.ToInt32(lengthBuffer, 0);
        if (payloadLength <= 0 || payloadLength > 1_000_000)
        {
            throw new InvalidOperationException($"Message payload length out of range: {payloadLength}");
        }

        var payloadBuffer = new byte[payloadLength];
        var totalRead = 0;
        while (totalRead < payloadLength)
        {
            var chunk = await stream.ReadAsync(payloadBuffer.AsMemory(totalRead, payloadLength - totalRead)).ConfigureAwait(false);
            if (chunk == 0)
            {
                return null;
            }
            totalRead += chunk;
        }

        var json = Encoding.UTF8.GetString(payloadBuffer);
        return JsonSerializer.Deserialize<NetworkMessage>(json, _jsonOptions);
    }

    private async Task BroadcastRoomStateAsync(RoomSession room, string messageType, object payload)
    {
        foreach (var player in room.Players.Values)
        {
            if (player.Client.Connected)
            {
                await SendMessageAsync(player, new NetworkMessage
                {
                    Type = messageType,
                    RoomCode = room.RoomCode,
                    Data = payload,
                    Message = "Room state updated"
                }).ConfigureAwait(false);
            }
        }
    }

    private static string GenerateRoomCode()
    {
