                RequestId = message.RequestId,
                Success = false,
                Error = "Mã phòng không tồn tại hoặc đã đóng."
            });
            return;
        }

        if (room.Players.Count >= room.Capacity)
        {
            await SendMessageAsync(session, new NetworkMessage
            {
                Type = MessageTypes.JoinRoomResult,
                RequestId = message.RequestId,
                Success = false,
                Error = "Phòng đã đầy."
            });
            return;
        }

        if (session.Room != null)
        {
            await HandleLeaveRoomAsync(session);
        }

        room.Players[session.PlayerId] = session;
        session.Room = room;
        session.Role = "Student";

        await BroadcastRoomStateAsync(room, MessageTypes.RoomStateUpdate, new
        {
            roomCode = room.RoomCode,
            role = session.Role,
            players = room.Players.Values.Select(p => new { playerId = p.PlayerId, displayname = p.DisplayName, role = p.Role }).ToArray(),
            count = room.Players.Count,
            capacity = room.Capacity,
            mode = room.Mode,
            lessonId = room.LessonId,
            durationSeconds = room.DurationSeconds
        });

        await SendMessageAsync(session, new NetworkMessage
        {
            Type = MessageTypes.JoinRoomResult,
            RequestId = message.RequestId,
            Success = true,
            RoomCode = room.RoomCode,
            Data = new { roomCode = room.RoomCode, role = session.Role }
        });
    }

    private async Task HandleLeaveRoomAsync(PlayerSession session)
    {
        if (session.Room == null)
        {
            return;
        }

        var room = session.Room;
        room.Players.TryRemove(session.PlayerId, out _);

        await BroadcastRoomStateAsync(room, MessageTypes.PlayerDisconnected, new
        {
            roomCode = room.RoomCode,
            playerId = session.PlayerId,
            displayName = session.DisplayName,
            remainingCount = room.Players.Count
        });

        if (room.Players.Count == 0)
        {
            _rooms.TryRemove(room.RoomCode, out _);
        }
        else
        {
            var newHost = room.Players.Values.FirstOrDefault();
            if (newHost != null && !string.Equals(room.HostPlayerId, newHost.PlayerId, StringComparison.Ordinal))
            {
                room.HostPlayerId = newHost.PlayerId;
                newHost.Role = "Teacher";
            }
        }

        session.Room = null;
        session.Role = "Student";
        session.HandRaised = false;
    }

    private async Task HandleStartGameAsync(PlayerSession session)
    {
        if (session.Room == null)
        {
            await SendMessageAsync(session, new NetworkMessage
            {
                Type = MessageTypes.Error,
                Error = "Bạn chưa ở trong phòng nào."
            });
            return;
        }

        var room = session.Room;
        if (!string.Equals(session.PlayerId, room.HostPlayerId, StringComparison.Ordinal))
        {
            await SendMessageAsync(session, new NetworkMessage
            {
                Type = MessageTypes.Error,
                Error = "Chỉ giáo viên mới bắt đầu trò chơi."
            });
            return;
        }

        room.Started = true;
        room.CurrentQuestionIndex = 0;
        await BroadcastRoomStateAsync(room, MessageTypes.StartCountdown, new
        {
            roomCode = room.RoomCode,
            startDelaySeconds = 3,
            lessonId = room.LessonId,
            mode = room.Mode
        });
        await SendMessageAsync(session, new NetworkMessage
        {
            Type = MessageTypes.StartCountdown,
            RoomCode = room.RoomCode,
            Success = true,
            Message = "Bài học đã bắt đầu. Đang chuẩn bị câu hỏi đầu tiên."
        });
    }

    private async Task HandleAnswerSubmissionAsync(PlayerSession session, NetworkMessage message)
    {
        var questionIndex = message.QuestionIndex ?? 0;
        if (session.Room == null)
        {
            await SendMessageAsync(session, new NetworkMessage
            {
                Type = MessageTypes.Error,
                Error = "Không thể chấm điểm vì bạn chưa ở trong phòng."
            });
            return;
        }

        await SendMessageAsync(session, new NetworkMessage
        {
            Type = MessageTypes.AnswerResult,
            RequestId = message.RequestId,
            QuestionIndex = questionIndex,
            Success = true,
            Message = "Đã nhận câu trả lời. Kết quả sẽ được xử lý trên server chính thức khi gameplay bắt đầu.",
            Data = new { playerId = session.PlayerId, questionIndex = questionIndex, accepted = true }
        });
    }

    private async Task HandleDisconnectAsync(PlayerSession session)
    {
        _sessions.TryRemove(session.PlayerId, out _);
        if (session.Room != null)
        {
            await HandleLeaveRoomAsync(session).ConfigureAwait(false);
        }

        session.Stream.Dispose();
        session.Client.Dispose();
    }

    private Task SendMessageAsync(PlayerSession session, NetworkMessage message)
    {
        var payload = JsonSerializer.SerializeToUtf8Bytes(message, _jsonOptions);
        var header = BitConverter.GetBytes(payload.Length);
        var buffer = new byte[header.Length + payload.Length];
        Buffer.BlockCopy(header, 0, buffer, 0, header.Length);
        Buffer.BlockCopy(payload, 0, buffer, header.Length, payload.Length);

        return session.Stream.WriteAsync(buffer).AsTask();
    }

    private async Task<NetworkMessage?> ReadMessageAsync(NetworkStream stream)
    {
        var lengthBuffer = new byte[4];
        var read = 0;
        while (read < lengthBuffer.Length)
        {
            var bytesRead = await stream.ReadAsync(lengthBuffer.AsMemory(read, lengthBuffer.Length - read)).ConfigureAwait(false);
            if (bytesRead == 0)
            {
                return null;
            }
            read += bytesRead;
        }

        var payloadLength = BitConverter.ToInt32(lengthBuffer, 0);
        if (payloadLength <= 0 || payloadLength > 1_000_000)
        {
            throw new InvalidOperationException($"Message payload length out of range: {payloadLength}");
        }

        var payloadBuffer = new byte[payloadLength];
        var totalRead = 0;
        while (totalRead < payloadLength)
        {
            var chunk = await stream.ReadAsync(payloadBuffer.AsMemory(totalRead, payloadLength - totalRead)).ConfigureAwait(false);
            if (chunk == 0)
            {
                return null;
            }
            totalRead += chunk;
        }

        var json = Encoding.UTF8.GetString(payloadBuffer);
        return JsonSerializer.Deserialize<NetworkMessage>(json, _jsonOptions);
    }

    private async Task BroadcastRoomStateAsync(RoomSession room, string messageType, object payload)
    {
        foreach (var player in room.Players.Values)
        {
            if (player.Client.Connected)
            {
                await SendMessageAsync(player, new NetworkMessage
                {
                    Type = messageType,
                    RoomCode = room.RoomCode,
                    Data = payload,
                    Message = "Room state updated"
                }).ConfigureAwait(false);
            }
        }
    }

    private static string GenerateRoomCode()
    {
        var chars = "ABCDEFGHJKLMNPRSTUVWXYZ23456789";
        var random = new Random();
        var builder = new StringBuilder();
        for (var i = 0; i < 6; i++)
        {
            builder.Append(chars[random.Next(chars.Length)]);
        }

        return builder.ToString();
    }
}

internal static class Program
{
    private const int DefaultPort = 7777;

    public static async Task Main()
    {
        var server = new TcpGameServer(IPAddress.Any, DefaultPort);
        Console.WriteLine("ClassroomQuiz TCP server starting...");
        Console.WriteLine("Press Ctrl+C to stop the server.");

        using var cancellationTokenSource = new CancellationTokenSource();
        Console.CancelKeyPress += (_, e) =>
        {
            e.Cancel = true;
            cancellationTokenSource.Cancel();
        };

        await server.StartAsync(cancellationTokenSource.Token);
    }
}
