2. using System.Net.Sockets;
3. using Unity.Netcode;
4. using Unity.Services.Authentication;
5. using Unity.Services.Core;
6. using UnityEngine;
7. using UnityEngine.UI;
8. using TMPro;
9. public class RoomController : NetworkBehaviour
10. {
11.     [Header("UI Elements")]
12.     public TMP_Text txtNotification;
13.     public Button btnPlay;
14.     public string gameplaySceneName = "GamePlay";
15.     private async void Start()
16.     {
17.         if (btnPlay != null)
18.         {
19.             btnPlay.gameObject.SetActive(false);
20.             btnPlay.onClick.AddListener(StartGame);
21.         }
22.         while (UnityServices.State != ServicesInitializationState.Initialized || !AuthenticationService.Instance.IsSignedIn)
23.         {
24.             await System.Threading.Tasks.Task.Delay(100);
25.             if (this == null) return;
26.         }
27.         string myIp = GetLocalIPAddress();
28.         try { await AuthenticationService.Instance.UpdatePlayerNameAsync(myIp); } catch { }
29.         if (NetworkManager.Singleton != null)
30.         {
31.             NetworkManager.Singleton.OnClientConnectedCallback += OnClientConnected;
32.             NetworkManager.Singleton.OnClientDisconnectCallback += OnClientDisconnected;
33.         }
34.     }
35.     public override void OnNetworkSpawn()
36.     {
37.         if (IsServer)
38.         {
39.             UpdateNotificationClientRpc($"Host (IP: {GetLocalIPAddress()}) đã tạo phòng!");
40.             InvokeRepeating(nameof(CheckPlayersAndEnablePlayButton), 0.5f, 0.2f);
41.         }
42.     }
43.     private void OnClientConnected(ulong clientId)
44.     {
45.         if (IsServer && clientId != NetworkManager.Singleton.LocalClientId)
46.         {
47.             UpdateNotificationClientRpc($"Một Client vừa tham gia phòng!");
48.         }
49.     }
50.     private void OnClientDisconnected(ulong clientId)
51.     {
52.         if (IsServer)
53.         {
54.             UpdateNotificationClientRpc($"Một Client đã rời phòng!");
55.         }
56.     }
57.     private void CheckPlayersAndEnablePlayButton()
58.     {
59.         if (!IsServer || btnPlay == null) return;
60.         int players = NetworkManager.Singleton.ConnectedClientsIds.Count;
61.         btnPlay.gameObject.SetActive(players >= 2);
62.     }
63.     [ClientRpc]
64.     private void UpdateNotificationClientRpc(string message)
65.     {
66.         if (txtNotification != null)
67.             txtNotification.text = message;
68.     }
69.     private void StartGame()
70.     {
71.         if (IsServer)
72.         {
73.             NetworkManager.Singleton.SceneManager.LoadScene(gameplaySceneName, UnityEngine.SceneManagement.LoadSceneMode.Single);
74.         }
75.     }
76.     public static string GetLocalIPAddress()
77.     {
78.         var host = Dns.GetHostEntry(Dns.GetHostName());
79.         foreach (var ip in host.AddressList)
80.         {
81.             if (ip.AddressFamily == AddressFamily.InterNetwork) return ip.ToString();
82.         }
83.         return "Unknown IP";
84.     }
85. }
