480.     private async Task<NetworkMessage?> ReadMessageAsync(NetworkStream stream)
481.     {
482.         var lengthBuffer = new byte[4];
483.         var read = 0;
484.         while (read < lengthBuffer.Length)
485.         {
486.             var bytesRead = await stream.ReadAsync(lengthBuffer.AsMemory(read, lengthBuffer.Length - read)).ConfigureAwait(false);
487.             if (bytesRead == 0)
488.             {
489.                 return null;
490.             }
491.             read += bytesRead;
492.         }
493. 
494.         var payloadLength = BitConverter.ToInt32(lengthBuffer, 0);
495.         if (payloadLength <= 0 || payloadLength > 1_000_000)
496.         {
497.             throw new InvalidOperationException($"Message payload length out of range: {payloadLength}");
498.         }
499. 
500.         var payloadBuffer = new byte[payloadLength];
501.         var totalRead = 0;
502.         while (totalRead < payloadLength)
503.         {
504.             var chunk = await stream.ReadAsync(payloadBuffer.AsMemory(totalRead, payloadLength - totalRead)).ConfigureAwait(false);
505.             if (chunk == 0)
506.             {
507.                 return null;
508.             }
509.             totalRead += chunk;
510.         }
511. 
512.         var json = Encoding.UTF8.GetString(payloadBuffer);
513.         return JsonSerializer.Deserialize<NetworkMessage>(json, _jsonOptions);
514.     }
