using System.Collections.Concurrent;
using System.IO;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using System.Threading.Tasks;
using UnityEngine;

namespace ClassroomQuiz.Network
{
    public sealed class NetworkMessage
    {
        public string Type { get; set; } = "";
        public string RequestId { get; set; } = "";
        public string RoomCode { get; set; }
        public string PlayerName { get; set; }
        public string Role { get; set; }
        public string Mode { get; set; }
        public int? LessonId { get; set; }
        public int? QuestionIndex { get; set; }
        public int? DurationSeconds { get; set; }
        public string Error { get; set; }
        public bool? Success { get; set; }
        public string Message { get; set; }
        public string Payload { get; set; }
        public object Data { get; set; }
        public string ServerAddress { get; set; }
        public int? ServerPort { get; set; }
    }

    public enum ConnectionState
    {
        Disconnected,
        Connecting,
        Connected,
        Failed
    }

    public sealed class TcpGameClient : MonoBehaviour
    {
        private readonly ConcurrentQueue<Action> _mainThreadActions = new ConcurrentQueue<Action>();
        private readonly JsonSerializerOptions _jsonOptions = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            WriteIndented = false
        };

        private TcpClient _client;
        private NetworkStream _stream;
        private Task _receiveLoopTask;
        private bool _disposed;

        public ConnectionState State { get; private set; } = ConnectionState.Disconnected;
        public string ServerAddress { get; private set; } = "127.0.0.1";
        public int ServerPort { get; private set; } = 7777;
        public string PlayerName { get; private set; } = "Guest";

        public event Action<NetworkMessage> MessageReceived;
        public event Action<string> ErrorReceived;

        public bool IsConnected => _client != null && _client.Connected && State == ConnectionState.Connected;

        public async Task<bool> ConnectAsync(string address, int port, string playerName)
        {
            if (State == ConnectionState.Connecting)
            {
                return false;
            }

            if (string.IsNullOrWhiteSpace(address))
            {
                address = "127.0.0.1";
            }

            State = ConnectionState.Connecting;
            ServerAddress = address;
            ServerPort = port;
            PlayerName = string.IsNullOrWhiteSpace(playerName) ? "Guest" : playerName;

            try
            {
                _client = new TcpClient();
                var timeoutTask = _client.ConnectAsync(address, port);
                var completed = await Task.WhenAny(timeoutTask, Task.Delay(5000));
                if (completed != timeoutTask)
                {
                    throw new TimeoutException("Kết nối TCP quá thời gian chờ.");
                }

                await timeoutTask;
                _stream = _client.GetStream();
                State = ConnectionState.Connected;
                _receiveLoopTask = Task.Run(ReceiveLoopAsync);

                await SendAsync(new NetworkMessage
                {
                    Type = "Hello",
                    PlayerName = PlayerName,
                    RequestId = Guid.NewGuid().ToString("N")
                });

                return true;
            }
            catch (Exception ex)
            {
                State = ConnectionState.Failed;
                ErrorReceived?.Invoke(ex.Message);
                Disconnect();
                return false;
            }
        }

        public async Task SendAsync(NetworkMessage message)
        {
            if (_client == null || !_client.Connected || _stream == null)
            {
                throw new InvalidOperationException("Chưa kết nối tới server TCP.");
            }

            var payload = Encoding.UTF8.GetBytes(JsonSerializer.Serialize(message, _jsonOptions));
            var lengthBuffer = BitConverter.GetBytes(payload.Length);
            var combined = new byte[lengthBuffer.Length + payload.Length];
            Buffer.BlockCopy(lengthBuffer, 0, combined, 0, lengthBuffer.Length);
            Buffer.BlockCopy(payload, 0, combined, lengthBuffer.Length, payload.Length);

            await _stream.WriteAsync(combined, 0, combined.Length);
            await _stream.FlushAsync();
        }

        private async Task ReceiveLoopAsync()
        {
            try
            {
                while (_client != null && _client.Connected)
                {
                    var message = await ReadMessageAsync();
                    if (message == null)
                    {
                        break;
                    }

                    _mainThreadActions.Enqueue(() => MessageReceived?.Invoke(message));
                }
            }
            catch (Exception ex)
            {
                _mainThreadActions.Enqueue(() => ErrorReceived?.Invoke(ex.Message));
            }
            finally
            {
                var disconnectAction = new Action(() =>
                {
                    State = ConnectionState.Disconnected;
                });
                _mainThreadActions.Enqueue(disconnectAction);
                Disconnect();
            }
        }

        private async Task<NetworkMessage> ReadMessageAsync()
        {
            var lengthBuffer = new byte[4];
            var totalRead = 0;

            while (totalRead < 4)
            {
                var read = await _stream.ReadAsync(lengthBuffer, totalRead, 4 - totalRead);
                if (read == 0)
                {
                    return null;
                }

                totalRead += read;
            }

            var payloadLength = BitConverter.ToInt32(lengthBuffer, 0);
            if (payloadLength <= 0 || payloadLength > 1_000_000)
            {
                throw new InvalidOperationException("Payload length không hợp lệ.");
            }

            var payloadBuffer = new byte[payloadLength];
            var payloadRead = 0;
            while (payloadRead < payloadLength)
            {
                var read = await _stream.ReadAsync(payloadBuffer, payloadRead, payloadLength - payloadRead);
                if (read == 0)
                {
                    return null;
                }

                payloadRead += read;
            }

            var json = Encoding.UTF8.GetString(payloadBuffer);
            return JsonSerializer.Deserialize<NetworkMessage>(json, _jsonOptions);
        }

        private void Update()
        {
            while (_mainThreadActions.TryDequeue(out var action))
            {
                action?.Invoke();
            }
        }

        public void Disconnect()
        {
            if (_disposed)
            {
                return;
            }

            _disposed = true;
            try
            {
                _stream?.Close();
                _client?.Close();
            }
            catch (ObjectDisposedException)
            {
            }

            _stream = null;
            _client = null;
            State = ConnectionState.Disconnected;
        }

        private void OnDestroy()
        {
            Disconnect();
        }
    }
}
"}

{"path":"D:\Unity\BaitapLab\ClassroomQuiz\Assets\Scripts\UI\StartSceneUIController.cs","file_text":"using System.Collections.Generic;
using System.Threading.Tasks;
using ClassroomQuiz.Data;
using ClassroomQuiz.Network;
using TMPro;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace ClassroomQuiz.UI
{
    public class StartSceneUIController : MonoBehaviour
    {
        [Header("Main Menu")]
        public GameObject mainMenuPanel;
        public GameObject roomHubPanel;
        public GameObject createRoomPanel;
        public GameObject joinRoomPanel;
        public GameObject settingsPanel;
        public GameObject connectingPanel;
        public GameObject statusPanel;

        [Header("Labels")]
        public TMP_Text titleText;
        public TMP_Text infoText;
        public TMP_Text statusText;
        public TMP_Text roomStatusText;

        [Header("Buttons")]
        public Button playButton;
        public Button settingsButton;
        public Button exitButton;
        public Button backToMenuButton;
        public Button createRoomButton;
        public Button joinRoomButton;
        public Button submitCreateRoomButton;
        public Button submitJoinRoomButton;
        public Button retryConnectionButton;
        public Button backToHubButton;

        [Header("Forms")]
        public TMP_Dropdown modeDropdown;
        public TMP_Dropdown lessonDropdown;
        public TMP_Dropdown questionSetDropdown;
        public TMP_Dropdown durationDropdown;
        public TMP_InputField roomCodeInput;
        public TMP_InputField serverAddressInput;
        public TMP_InputField serverPortInput;
        public Slider volumeSlider;
        public Toggle soundToggle;

        [Header("Client")]
        public TcpGameClient tcpClient;

        private JsonLessonRepository _lessonRepository;
        private List<LessonDefinition> _lessons;
        private bool _isConnecting;

        private void Awake()
        {
            _lessonRepository = new JsonLessonRepository();
            _lessons = _lessonRepository.LoadLessons();
            EnsureClient();
            ShowMainMenu();
        }

        private void Start()
        {
            if (playButton != null)
            {
                playButton.onClick.AddListener(OnPlayClicked);
            }

            if (settingsButton != null)
            {
                settingsButton.onClick.AddListener(ShowSettingsPanel);
            }

            if (createRoomButton != null)
            {
                createRoomButton.onClick.AddListener(ShowCreateRoomPanel);
            }

            if (joinRoomButton != null)
            {
                joinRoomButton.onClick.AddListener(ShowJoinRoomPanel);
            }

            if (submitCreateRoomButton != null)
            {
                submitCreateRoomButton.onClick.AddListener(OnCreateRoomClicked);
            }

            if (submitJoinRoomButton != null)
            {
                submitJoinRoomButton.onClick.AddListener(OnJoinRoomClicked);
            }

            if (retryConnectionButton != null)
            {
                retryConnectionButton.onClick.AddListener(OnPlayClicked);
            }

            if (backToMenuButton != null)
            {
                backToMenuButton.onClick.AddListener(ShowMainMenu);
            }

            if (backToHubButton != null)
            {
                backToHubButton.onClick.AddListener(ShowRoomHub);
            }

            if (exitButton != null)
            {
                exitButton.onClick.AddListener(OnExitClicked);
            }

            ConfigureSettingsDefaults();
            PopulateLessonDropdown();
            RegisterTcpHandlers();
        }

        private void EnsureClient()
        {
            if (tcpClient == null)
            {
                var clientObject = new GameObject("TcpGameClient");
                clientObject.transform.SetParent(transform, false);
                tcpClient = clientObject.AddComponent<TcpGameClient>();
            }
        }

        private void ConfigureSettingsDefaults()
        {
            var savedAddress = PlayerPrefs.GetString("ClassroomQuiz.ServerAddress", "127.0.0.1");
            var savedPort = PlayerPrefs.GetInt("ClassroomQuiz.ServerPort", 7777);
            if (serverAddressInput != null)
            {
                serverAddressInput.text = savedAddress;
            }

            if (serverPortInput != null)
            {
                serverPortInput.text = savedPort.ToString();
            }

            if (volumeSlider != null)
            {
                volumeSlider.value = PlayerPrefs.GetFloat("ClassroomQuiz.Volume", 1f);
            }

            if (soundToggle != null)
            {
                soundToggle.isOn = PlayerPrefs.GetInt("ClassroomQuiz.SoundEnabled", 1) == 1;
            }
        }

        private void PopulateLessonDropdown()
        {
            if (lessonDropdown == null)
            {
                return;
            }

            var options = new List<string>();
            foreach (var lesson in _lessons)
            {
                options.Add(lesson.status == LessonStatus.Ready ? $"{lesson.lessonId}. {lesson.title} (Ready)" : $"{lesson.lessonId}. {lesson.title} (Draft)");
            }

            lessonDropdown.ClearOptions();
            lessonDropdown.AddOptions(options);

            if (questionSetDropdown != null)
            {
                questionSetDropdown.ClearOptions();
                questionSetDropdown.AddOptions(new List<string> { "Default local dataset", "Teacher edited version" });
            }

            if (durationDropdown != null)
            {
                durationDropdown.ClearOptions();
                durationDropdown.AddOptions(new List<string> { "5 s", "10 s", "15 s", "20 s" });
                durationDropdown.value = 2;
            }

            if (modeDropdown != null)
            {
                modeDropdown.ClearOptions();
                modeDropdown.AddOptions(new List<string> { "Học", "Thi" });
                modeDropdown.value = 0;
            }
        }

        private void RegisterTcpHandlers()
        {
            if (tcpClient == null)
            {
                return;
            }

            tcpClient.MessageReceived += OnMessageReceived;
            tcpClient.ErrorReceived += OnConnectionError;
        }

        public async void OnPlayClicked()
        {
            if (_isConnecting)
            {
                return;
            }

            _isConnecting = true;
            ShowConnectingOverlay("Connecting to server...");
            var address = serverAddressInput != null ? serverAddressInput.text.Trim() : "127.0.0.1";
            var portText = serverPortInput != null ? serverPortInput.text.Trim() : "7777";

            if (!int.TryParse(portText, out var port))
            {
                port = 7777;
            }

            PlayerPrefs.SetString("ClassroomQuiz.ServerAddress", address);
            PlayerPrefs.SetInt("ClassroomQuiz.ServerPort", port);

            try
            {
                var playerName = PlayerPrefs.GetString("ClassroomQuiz.DisplayName", "Guest");
                var connected = await tcpClient.ConnectAsync(address, port, playerName);
                if (!connected)
                {
                    ShowConnectionFailure("Không thể kết nối máy chủ. Kiểm tra IP/port hoặc server đang chạy.");
                    _isConnecting = false;
                    return;
                }

                if (connectingPanel != null)
                {
                    connectingPanel.SetActive(false);
                }

                ShowRoomHub();
                _isConnecting = false;
            }
            catch (System.Exception ex)
            {
                ShowConnectionFailure(ex.Message);
                _isConnecting = false;
            }
        }

        private void OnMessageReceived(NetworkMessage message)
        {
            if (message == null)
            {
                return;
            }

            if (statusText != null)
            {
                statusText.text = message.Message ?? message.Error ?? "Server phản hồi.";
            }

            switch (message.Type)
            {
                case "Welcome":
                    SetRoomStatus("Đã kết nối. Chọn một phòng để bắt đầu.");
                    break;
                case "CreateRoomResult":
                    if (message.Success == true)
                    {
                        SetRoomStatus($"Phòng {message.RoomCode} đã được tạo.");
                    }
                    else
                    {
                        SetRoomStatus(message.Error ?? "Không thể tạo phòng.");
                    }
                    break;
                case "JoinRoomResult":
                    if (message.Success == true)
                    {
                        SetRoomStatus($"Đã vào phòng {message.RoomCode}.");
                    }
                    else
                    {
                        SetRoomStatus(message.Error ?? "Không thể tham gia phòng.");
                    }
                    break;
                case "RoomStateUpdate":
                    SetRoomStatus($"Số người: {message.Data?.ToString() ?? ""}");
                    break;
                case "Error":
                    SetRoomStatus(message.Error ?? "Máy chủ báo lỗi.");
                    break;
            }
        }

        private void OnConnectionError(string error)
        {
            ShowConnectionFailure(error);
        }

        public void OnCreateRoomClicked()
        {
            var mode = modeDropdown != null ? modeDropdown.options[modeDropdown.value].text : "Học";
            var selectedLesson = lessonDropdown != null ? GetSelectedLesson() : null;
            var durationSeconds = durationDropdown != null ? ParseDurationFromDropdown(durationDropdown.value) : 15;

            if (selectedLesson == null)
            {
                SetRoomStatus("Bài học chưa có dữ liệu hợp lệ.");
                return;
            }

            if (!selectedLesson.IsReadyForRoom)
            {
                SetRoomStatus("Bài đang ở trạng thái Draft hoặc thiếu câu hỏi hợp lệ. Chọn một bài đã sẵn sàng.");
                return;
            }

            if (tcpClient == null || !tcpClient.IsConnected)
            {
                ShowConnectionFailure("Bạn chưa kết nối tới server. Hãy nhấn Play trước.");
                return;
            }

            var msg = new NetworkMessage
            {
                Type = "CreateRoomRequest",
                RequestId = System.Guid.NewGuid().ToString("N"),
                Mode = mode,
                LessonId = selectedLesson.lessonId,
                DurationSeconds = durationSeconds,
                PlayerName = PlayerPrefs.GetString("ClassroomQuiz.DisplayName", "Guest")
            };

            _ = tcpClient.SendAsync(msg);
            SetRoomStatus("Đang gửi yêu cầu tạo phòng...");
        }

        public void OnJoinRoomClicked()
        {
            if (tcpClient == null || !tcpClient.IsConnected)
            {
                ShowConnectionFailure("Bạn chưa kết nối tới server. Hãy nhấn Play trước.");
                return;
            }

            var roomCode = roomCodeInput != null ? roomCodeInput.text.Trim().ToUpperInvariant() : string.Empty;
            if (string.IsNullOrWhiteSpace(roomCode))
            {
                SetRoomStatus("Mã phòng không được để trống.");
                return;
            }

            var message = new NetworkMessage
            {
                Type = "JoinRoomRequest",
                RequestId = System.Guid.NewGuid().ToString("N"),
                RoomCode = roomCode,
                PlayerName = PlayerPrefs.GetString("ClassroomQuiz.DisplayName", "Guest")
            };

            _ = tcpClient.SendAsync(message);
            SetRoomStatus("Đang gửi yêu cầu tham gia phòng...");
        }

        public void ShowMainMenu()
        {
            SetPanelState(mainMenuPanel, true);
            SetPanelState(roomHubPanel, false);
            SetPanelState(createRoomPanel, false);
            SetPanelState(joinRoomPanel, false);
            SetPanelState(settingsPanel, false);
            SetPanelState(connectingPanel, false);
        }

        public void ShowRoomHub()
        {
            SetPanelState(mainMenuPanel, false);
            SetPanelState(roomHubPanel, true);
            SetPanelState(createRoomPanel, false);
            SetPanelState(joinRoomPanel, false);
            SetPanelState(settingsPanel, false);
            SetPanelState(connectingPanel, false);
        }

        public void ShowCreateRoomPanel()
        {
            SetPanelState(roomHubPanel, false);
            SetPanelState(createRoomPanel, true);
            SetPanelState(joinRoomPanel, false);
            SetPanelState(settingsPanel, false);
        }

        public void ShowJoinRoomPanel()
        {
            SetPanelState(roomHubPanel, false);
            SetPanelState(createRoomPanel, false);
            SetPanelState(joinRoomPanel, true);
            SetPanelState(settingsPanel, false);
        }

        private void ShowSettingsPanel()
        {
            SetPanelState(mainMenuPanel, false);
            SetPanelState(settingsPanel, true);
            SetPanelState(roomHubPanel, false);
        }

        public void ShowConnectingOverlay(string message)
        {
            if (connectingPanel != null)
            {
                connectingPanel.SetActive(true);
            }

            if (statusText != null)
            {
                statusText.text = message;
            }
        }

        private void ShowConnectionFailure(string message)
        {
            ShowConnectingOverlay(message);
            if (retryConnectionButton != null)
            {
                retryConnectionButton.gameObject.SetActive(true);
            }

            SetRoomStatus(message);
            _isConnecting = false;
        }

        public void SaveSettings()
        {
            PlayerPrefs.SetString("ClassroomQuiz.ServerAddress", serverAddressInput != null ? serverAddressInput.text.Trim() : "127.0.0.1");
            PlayerPrefs.SetInt("ClassroomQuiz.ServerPort", int.TryParse(serverPortInput != null ? serverPortInput.text.Trim() : "7777", out var port) ? port : 7777);
            PlayerPrefs.SetFloat("ClassroomQuiz.Volume", volumeSlider != null ? volumeSlider.value : 1f);
            PlayerPrefs.SetInt("ClassroomQuiz.SoundEnabled", soundToggle != null && soundToggle.isOn ? 1 : 0);
            PlayerPrefs.Save();
            SetRoomStatus("Đã lưu cài đặt máy chủ.");
        }

        private void OnExitClicked()
        {
#if UNITY_EDITOR
            Debug.Log("Exit button pressed in Editor; no Unity editor shutdown performed.");
#else
            Application.Quit();
#endif
        }

        private LessonDefinition GetSelectedLesson()
        {
            if (lessonDropdown == null)
            {
                return null;
            }

            var index = Mathf.Clamp(lessonDropdown.value, 0, _lessons.Count - 1);
            return _lessons[index];
        }

        private int ParseDurationFromDropdown(int selectedIndex)
        {
            var values = new[] { 5, 10, 15, 20 };
            return selectedIndex >= 0 && selectedIndex < values.Length ? values[selectedIndex] : 15;
        }

        private void SetRoomStatus(string message)
        {
            if (roomStatusText != null)
            {
                roomStatusText.text = message;
            }
            else if (statusText != null)
            {
                statusText.text = message;
            }
        }

        private static void SetPanelState(GameObject panel, bool active)
        {
            if (panel != null)
            {
                panel.SetActive(active);
            }
        }
    }
}
