using System.Collections.Generic;
using System.IO;
using UnityEngine;

namespace ClassroomQuiz.Data
{
    public enum LessonStatus
    {
        Draft,
        Ready
    }

    [Serializable]
    public class LessonQuestionData
    {
        public string questionId = "";
        public int sequenceIndex;
        public string prompt = "";
        public List<string> options = new List<string> { "", "", "", "" };
        public int correctIndex;
        public string explanation = "";
    }

    [Serializable]
    public class LessonDefinition
    {
        public int lessonId;
        public string title = "";
        public LessonStatus status;
        public bool isDemo;
        public string summary = "";
        public int defaultQuestionDurationSeconds = 15;
        public List<LessonQuestionData> questions = new List<LessonQuestionData>();

        public bool IsReadyForRoom => status == LessonStatus.Ready && questions != null && questions.Count >= 2 && questions.Count <= 5 && ValidateQuestions();

        public bool ValidateQuestions()
        {
            if (questions == null || questions.Count < 2 || questions.Count > 5)
            {
                return false;
            }

            foreach (var question in questions)
            {
                if (string.IsNullOrWhiteSpace(question.prompt))
                {
                    return false;
                }

                if (question.options == null || question.options.Count != 4)
                {
                    return false;
                }

                if (question.options.Exists(string.IsNullOrWhiteSpace))
                {
                    return false;
                }

                if (question.correctIndex < 0 || question.correctIndex > 3)
                {
                    return false;
                }
            }

            return true;
        }
    }

    [Serializable]
    public class LessonRepositoryData
    {
        public List<LessonDefinition> lessons = new List<LessonDefinition>();
    }

    public interface IQuestionRepository
    {
        List<LessonDefinition> LoadLessons();
        LessonDefinition GetLesson(int lessonId);
        bool SaveLessons(List<LessonDefinition> lessons);
    }

    public sealed class JsonLessonRepository : IQuestionRepository
    {
        private readonly string _persistentPath;
        private readonly string _defaultDataPath;

        public JsonLessonRepository()
        {
            var baseDirectory = Path.Combine(Application.persistentDataPath, "ClassroomQuiz");
            Directory.CreateDirectory(baseDirectory);
            _persistentPath = Path.Combine(baseDirectory, "ClassroomQuizLessons.json");

            var streamingAssetsPath = Application.streamingAssetsPath;
            _defaultDataPath = string.IsNullOrEmpty(streamingAssetsPath)
                ? Path.Combine(Application.dataPath, "StreamingAssets", "ClassroomQuizLessons.json")
                : Path.Combine(streamingAssetsPath, "ClassroomQuizLessons.json");

            EnsureDefaultFileExists();
        }

        public List<LessonDefinition> LoadLessons()
        {
            var sourcePath = File.Exists(_persistentPath) ? _persistentPath : _defaultDataPath;
            if (!File.Exists(sourcePath))
            {
                return BuildDefaultLessons();
            }

            try
            {
                var json = File.ReadAllText(sourcePath);
                var data = JsonUtility.FromJson<LessonRepositoryData>(json);
                if (data == null || data.lessons == null || data.lessons.Count == 0)
                {
                    return BuildDefaultLessons();
                }

                return data.lessons;
            }
            catch (Exception)
            {
                return BuildDefaultLessons();
            }
        }

        public LessonDefinition GetLesson(int lessonId)
        {
            var lessons = LoadLessons();
            foreach (var lesson in lessons)
            {
                if (lesson.lessonId == lessonId)
                {
                    return lesson;
                }
            }

            return lessons.Count > 0 ? lessons[0] : new LessonDefinition();
        }

        public bool SaveLessons(List<LessonDefinition> lessons)
        {
            try
            {
                var repositoryData = new LessonRepositoryData { lessons = lessons };
                var json = JsonUtility.ToJson(repositoryData, true);
                File.WriteAllText(_persistentPath, json);
                return true;
            }
            catch (Exception)
            {
                return false;
            }
        }

        public static List<LessonDefinition> BuildDefaultLessons()
        {
            var lessons = new List<LessonDefinition>();
            for (var i = 1; i <= 42; i++)
            {
                var lesson = new LessonDefinition
                {
                    lessonId = i,
                    title = $"Bài {i}",
                    status = LessonStatus.Draft,
                    isDemo = false,
                    summary = "Đang chờ giáo viên chỉnh sửa câu hỏi.",
                    defaultQuestionDurationSeconds = 15,
                    questions = new List<LessonQuestionData>()
                };

                if (i == 1)
                {
                    lesson.title = "Bài 1 (Demo)";
                    lesson.status = LessonStatus.Ready;
                    lesson.isDemo = true;
                    lesson.summary = "Demo — đề mẫu, cần giáo viên rà soát lại trước khi dùng chính thức.";
                    lesson.questions = new List<LessonQuestionData>
                    {
                        new LessonQuestionData
                        {
                            questionId = "demo-1",
                            sequenceIndex = 1,
                            prompt = "Diện tích của một tam giác có đáy 12 cm và chiều cao 8 cm là bao nhiêu?",
                            options = new List<string> { "48 cm²", "64 cm²", "96 cm²", "72 cm²" },
                            correctIndex = 2,
                            explanation = "Diện tích tam giác = (đáy × chiều cao) / 2 = (12 × 8) / 2 = 48 cm²."
                        },
                        new LessonQuestionData
                        {
                            questionId = "demo-2",
                            sequenceIndex = 2,
                            prompt = "Nếu tăng đáy lên gấp đôi nhưng giữ nguyên chiều cao, diện tích tam giác mới sẽ thay đổi như thế nào?",
                            options = new List<string> { "Giảm đi một nửa", "Không đổi", "Tăng gấp đôi", "Tăng gấp bốn" },
                            correctIndex = 2,
                            explanation = "Diện tích tam giác tỉ lệ thuận với đáy, nên nếu đáy tăng gấp đôi thì diện tích cũng tăng gấp đôi."
                        },
                        new LessonQuestionData
                        {
                            questionId = "demo-3",
                            sequenceIndex = 3,
                            prompt = "Công thức tính diện tích tam giác là gì?",
                            options = new List<string> { "a × b", "(a × h) / 2", "a + b + c", "(a + b) / 2" },
                            correctIndex = 1,
                            explanation = "Công thức tính diện tích tam giác là (đáy × chiều cao) / 2."
                        }
                    };
                }

                lessons.Add(lesson);
            }

            return lessons;
        }

        private void EnsureDefaultFileExists()
        {
            if (!File.Exists(_defaultDataPath))
            {
                var directory = Path.GetDirectoryName(_defaultDataPath);
                if (!string.IsNullOrEmpty(directory))
                {
                    Directory.CreateDirectory(directory);
                }

                var data = new LessonRepositoryData { lessons = BuildDefaultLessons() };
                var json = JsonUtility.ToJson(data, true);
                File.WriteAllText(_defaultDataPath, json);
            }
        }
    }
}
