{"path":"D:\Unity\BaitapLab\ClassroomQuiz\Assets\Scripts\UI\LoginSceneUIController.cs","file_text":"using TMPro;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace ClassroomQuiz.UI
{
    public class LoginSceneUIController : MonoBehaviour
    {
        [Header("Panels")]
        public GameObject loginPanel;
        public GameObject registerPanel;

        [Header("Fields")]
        public TMP_InputField usernameInput;
        public TMP_InputField passwordInput;
        public TMP_InputField registerUsernameInput;
        public TMP_InputField registerPasswordInput;

        [Header("Buttons")]
        public Button loginButton;
        public Button registerButton;
        public Button switchToRegisterButton;
        public Button switchToLoginButton;
        public Button guestButton;

        [Header("Text")]
        public TMP_Text statusText;

        private void Awake()
        {
            if (statusText != null)
            {
                statusText.text = "Đăng nhập máy chủ tài khoản sẽ được tích hợp sau; hiện dùng chế độ Demo.";
            }

            ShowLoginPanel();
        }

        private void Start()
        {
            if (loginButton != null)
            {
                loginButton.onClick.AddListener(OnLoginPressed);
            }

            if (registerButton != null)
            {
                registerButton.onClick.AddListener(OnRegisterPressed);
            }

            if (switchToRegisterButton != null)
            {
                switchToRegisterButton.onClick.AddListener(ShowRegisterPanel);
            }

            if (switchToLoginButton != null)
            {
                switchToLoginButton.onClick.AddListener(ShowLoginPanel);
            }

            if (guestButton != null)
            {
                guestButton.onClick.AddListener(OnGuestPressed);
            }
        }

        private void OnLoginPressed()
        {
            var username = usernameInput != null ? usernameInput.text.Trim() : string.Empty;
            var password = passwordInput != null ? passwordInput.text.Trim() : string.Empty;

            if (string.IsNullOrWhiteSpace(username) || string.IsNullOrWhiteSpace(password))
            {
                SetStatus("Vui lòng nhập tên tài khoản và mật khẩu.");
                return;
            }

            PlayerPrefs.SetString("ClassroomQuiz.DisplayName", username);
            SetStatus("Tài khoản demo đã lưu cục bộ. Server authentication sẽ được tích hợp sau.");
            SceneManager.LoadScene("StartScene");
        }

        private void OnRegisterPressed()
        {
            var username = registerUsernameInput != null ? registerUsernameInput.text.Trim() : string.Empty;
            var password = registerPasswordInput != null ? registerPasswordInput.text.Trim() : string.Empty;

            if (string.IsNullOrWhiteSpace(username) || string.IsNullOrWhiteSpace(password))
            {
                SetStatus("Vui lòng điền tên tài khoản và mật khẩu để đăng ký demo.");
                return;
            }

            PlayerPrefs.SetString("ClassroomQuiz.DisplayName", username);
            SetStatus("Tính năng đăng ký máy chủ sẽ được tích hợp sau; hiện dùng chế độ demo.");
            SceneManager.LoadScene("StartScene");
        }

        private void OnGuestPressed()
        {
            var guestName = "Guest" + Random.Range(1000, 9999);
            PlayerPrefs.SetString("ClassroomQuiz.DisplayName", guestName);
            SetStatus("Đang tiếp tục với tài khoản demo.");
            SceneManager.LoadScene("StartScene");
        }

        private void ShowLoginPanel()
        {
            if (loginPanel != null)
            {
                loginPanel.SetActive(true);
            }

            if (registerPanel != null)
            {
                registerPanel.SetActive(false);
            }
        }

        private void ShowRegisterPanel()
        {
            if (loginPanel != null)
            {
                loginPanel.SetActive(false);
            }

            if (registerPanel != null)
            {
                registerPanel.SetActive(true);
            }
        }

        private void SetStatus(string message)
        {
            if (statusText != null)
            {
                statusText.text = message;
            }
        }
    }
}
"}

