271.                     if (message.Success == true)
272.                     {
273.                         SetRoomStatus($"Phòng {message.RoomCode} đã được tạo.");
274.                     }
275.                     else
276.                     {
277.                         SetRoomStatus(message.Error ?? "Không thể tạo phòng.");
278.                     }
279.                     break;
280.                 case "JoinRoomResult":
281.                     if (message.Success == true)
282.                     {
283.                         SetRoomStatus($"Đã vào phòng {message.RoomCode}.");
284.                     }
285.                     else
286.                     {
287.                         SetRoomStatus(message.Error ?? "Không thể tham gia phòng.");
288.                     }
289.                     break;
290.                 case "RoomStateUpdate":
291.                     SetRoomStatus($"Số người: {message.Data?.ToString() ?? ""}");
