95.     };
96. 
97.     public TcpGameServer(IPAddress ipAddress, int port)
98.     {
99.         _listener = new TcpListener(ipAddress, port);
100.     }
101. 
102.     public async Task StartAsync(CancellationToken cancellationToken = default)
103.     {
104.         _listener.Start();
105.         Console.WriteLine($"TCP server listening on {_listener.LocalEndpoint}.");
106.         try
107.         {
108.             while (!cancellationToken.IsCancellationRequested)
109.             {
110.                 var client = await _listener.AcceptTcpClientAsync(cancellationToken).ConfigureAwait(false);
111.                 _ = Task.Run(() => HandleClientAsync(client), cancellationToken);
112.             }
113.         }
114.         catch (OperationCanceledException)
115.         {
116.             Console.WriteLine("Server shutdown requested.");
117.         }
118.         finally
119.         {
120.             _listener.Stop();
121.         }
122.     }
123. 
124.     private async Task HandleClientAsync(TcpClient client)
125.     {
126.         var session = new PlayerSession
127.         {
128.             PlayerId = Guid.NewGuid().ToString("N"),
129.             DisplayName = "Guest",
130.             Client = client,
131.             Stream = client.GetStream()
132.         };
133. 
134.         _sessions[session.PlayerId] = session;
135.         await SendMessageAsync(session, new NetworkMessage
136.         {
137.             Type = MessageTypes.Welcome,
138.             Message = "Kết nối TCP thành công. Chờ yêu cầu tạo phòng hoặc tham gia phòng.",
139.             ServerAddress = ((IPEndPoint)client.Client.LocalEndPoint!).Address.ToString(),
140.             ServerPort = ((IPEndPoint)client.Client.LocalEndPoint!).Port
141.         });
142. 
143.         try
144.         {
145.             while (client.Connected)
146.             {
147.                 var message = await ReadMessageAsync(session.Stream).ConfigureAwait(false);
148.                 if (message == null)
149.                 {
150.                     break;
151.                 }
152. 
153.                 session.LastPingUtc = DateTime.UtcNow;
154.                 await ProcessMessageAsync(session, message).ConfigureAwait(false);
155.             }
156.         }
157.         catch (IOException ex)
158.         {
159.             Console.WriteLine($"Client disconnected with IO exception: {ex.Message}");
160.         }
161.         catch (SocketException ex)
162.         {
163.             Console.WriteLine($"Client socket error: {ex.Message}");
164.         }
165.         finally
166.         {
167.             await HandleDisconnectAsync(session).ConfigureAwait(false);
168.         }
169.     }
170. 
171.     private async Task ProcessMessageAsync(PlayerSession session, NetworkMessage message)
172.     {
173.         switch (message.Type)
174.         {
175.             case MessageTypes.Hello:
176.                 if (!string.IsNullOrWhiteSpace(message.PlayerName))
177.                 {
178.                     session.DisplayName = message.PlayerName.Trim();
179.                 }
180.                 await SendMessageAsync(session, new NetworkMessage
181.                 {
182.                     Type = MessageTypes.Welcome,
183.                     Message = $"Xin chào {session.DisplayName}. Server đang nhận yêu cầu phòng.",
184.                     Data = new { playerId = session.PlayerId }
185.                 });
186.                 break;
187. 
188.             case MessageTypes.CreateRoomRequest:
189.                 await HandleCreateRoomAsync(session, message).ConfigureAwait(false);
190.                 break;
191. 
192.             case MessageTypes.JoinRoomRequest:
193.                 await HandleJoinRoomAsync(session, message).ConfigureAwait(false);
194.                 break;
195. 
196.             case MessageTypes.LeaveRoomRequest:
197.                 await HandleLeaveRoomAsync(session).ConfigureAwait(false);
198.                 break;
199. 
200.             case MessageTypes.StartGameRequest:
201.                 await HandleStartGameAsync(session).ConfigureAwait(false);
202.                 break;
203. 
204.             case MessageTypes.HandRaised:
205.                 session.HandRaised = true;
206.                 await BroadcastRoomStateAsync(session.Room, MessageTypes.HandRaised, new { playerId = session.PlayerId, displayName = session.DisplayName, raised = true });
207.                 break;
208. 
209.             case MessageTypes.SubmitAnswerRequest:
210.                 await HandleAnswerSubmissionAsync(session, message).ConfigureAwait(false);
211.                 break;
212. 
213.             case MessageTypes.Ping:
214.                 await SendMessageAsync(session, new NetworkMessage { Type = MessageTypes.Pong, RequestId = message.RequestId });
215.                 break;
216. 
217.             default:
218.                 await SendMessageAsync(session, new NetworkMessage
219.                 {
220.                     Type = MessageTypes.Error,
221.                     Error = $"Unsupported message type: {message.Type}",
222.                     RequestId = message.RequestId
223.                 });
224.                 break;
225.         }
226.     }
227. 
228.     private async Task HandleCreateRoomAsync(PlayerSession session, NetworkMessage message)
229.     {
230.         if (session.Room != null)
231.         {
232.             await SendMessageAsync(session, new NetworkMessage
233.             {
234.                 Type = MessageTypes.Error,
235.                 RequestId = message.RequestId,
236.                 Error = "Người chơi đã ở trong phòng. Hãy rời phòng trước khi tạo phòng mới."
237.             });
238.             return;
239.         }
240. 
241.         var roomCode = GenerateRoomCode();
242.         var capacity = 40;
243.         var lessonId = message.LessonId ?? 1;
244.         var durationSeconds = message.DurationSeconds ?? 15;
245.         var mode = string.IsNullOrWhiteSpace(message.Mode) ? "Study" : message.Mode;
246.         var room = new RoomSession
247.         {
248.             RoomCode = roomCode,
249.             HostPlayerId = session.PlayerId,
250.             Mode = mode,
251.             LessonId = lessonId,
252.             DurationSeconds = durationSeconds,
253.             Capacity = capacity,
254.             Players = new ConcurrentDictionary<string, PlayerSession>()
255.         };
256. 
257.         room.Players[session.PlayerId] = session;
258.         session.Room = room;
259.         session.Role = "Teacher";
260.         _rooms[room.RoomCode] = room;
261. 
262.         await BroadcastRoomStateAsync(room, MessageTypes.RoomStateUpdate, new
263.         {
264.             roomCode = room.RoomCode,
265.             role = session.Role,
266.             players = room.Players.Values.Select(p => new { playerId = p.PlayerId, displayName = p.DisplayName, role = p.Role }).ToArray(),
267.             count = room.Players.Count,
268.             capacity = room.Capacity,
269.             mode = room.Mode,
270.             lessonId = room.LessonId,
271.             durationSeconds = room.DurationSeconds
272.         });
273. 
274.         await SendMessageAsync(session, new NetworkMessage
275.         {
276.             Type = MessageTypes.CreateRoomResult,
277.             RequestId = message.RequestId,
278.             Success = true,
279.             RoomCode = room.RoomCode,
280.             Message = $"Phòng {room.RoomCode} đã được tạo.",
281.             Data = new { roomCode = room.RoomCode, hostPlayerId = session.PlayerId }
282.         });
283.     }
284. 
285.     private async Task HandleJoinRoomAsync(PlayerSession session, NetworkMessage message)
286.     {
287.         var roomCode = (message.RoomCode ?? string.Empty).Trim();
288.         if (string.IsNullOrWhiteSpace(roomCode))
289.         {
290.             await SendMessageAsync(session, new NetworkMessage
291.             {
292.                 Type = MessageTypes.JoinRoomResult,
293.                 RequestId = message.RequestId,
