1. using System;
2. using System.Collections.Concurrent;
3. using System.IO;
4. using System.Net.Sockets;
5. using System.Text;
6. using System.Text.Json;
7. using System.Threading.Tasks;
8. using UnityEngine;
9. 
10. namespace ClassroomQuiz.Network
11. {
12.     public sealed class NetworkMessage
13.     {
14.         public string Type { get; set; } = "";
15.         public string RequestId { get; set; } = "";
16.         public string RoomCode { get; set; }
17.         public string PlayerName { get; set; }
18.         public string Role { get; set; }
19.         public string Mode { get; set; }
20.         public int? LessonId { get; set; }
21.         public int? QuestionIndex { get; set; }
22.         public int? DurationSeconds { get; set; }
23.         public string Error { get; set; }
24.         public bool? Success { get; set; }
25.         public string Message { get; set; }
26.         public string Payload { get; set; }
27.         public object Data { get; set; }
28.         public string ServerAddress { get; set; }
29.         public int? ServerPort { get; set; }
30.     }
31. 
32.     public enum ConnectionState
33.     {
34.         Disconnected,
35.         Connecting,
36.         Connected,
37.         Failed
38.     }
39. 
40.     public sealed class TcpGameClient : MonoBehaviour
41.     {
42.         private readonly ConcurrentQueue<Action> _mainThreadActions = new ConcurrentQueue<Action>();
43.         private readonly JsonSerializerOptions _jsonOptions = new JsonSerializerOptions
44.         {
45.             PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
46.             WriteIndented = false
47.         };
48. 
49.         private TcpClient _client;
50.         private NetworkStream _stream;
51.         private Task _receiveLoopTask;
52.         private bool _disposed;
53. 
54.         public ConnectionState State { get; private set; } = ConnectionState.Disconnected;
55.         public string ServerAddress { get; private set; } = "127.0.0.1";
56.         public int ServerPort { get; private set; } = 7777;
57.         public string PlayerName { get; private set; } = "Guest";
58. 
59.         public event Action<NetworkMessage> MessageReceived;
60.         public event Action<string> ErrorReceived;
61. 
62.         public bool IsConnected => _client != null && _client.Connected && State == ConnectionState.Connected;
63. 
64.         public async Task<bool> ConnectAsync(string address, int port, string playerName)
65.         {
66.             if (State == ConnectionState.Connecting)
67.             {
68.                 return false;
69.             }
70. 
71.             if (string.IsNullOrWhiteSpace(address))
72.             {
73.                 address = "127.0.0.1";
74.             }
75. 
76.             State = ConnectionState.Connecting;
77.             ServerAddress = address;
78.             ServerPort = port;
79.             PlayerName = string.IsNullOrWhiteSpace(playerName) ? "Guest" : playerName;
80. 
81.             try
82.             {
83.                 _client = new TcpClient();
84.                 var timeoutTask = _client.ConnectAsync(address, port);
85.                 var completed = await Task.WhenAny(timeoutTask, Task.Delay(5000));
86.                 if (completed != timeoutTask)
87.                 {
88.                     throw new TimeoutException("Kết nối TCP quá thời gian chờ.");
89.                 }
90. 
91.                 await timeoutTask;
92.                 _stream = _client.GetStream();
93.                 State = ConnectionState.Connected;
94.                 _receiveLoopTask = Task.Run(ReceiveLoopAsync);
95. 
96.                 await SendAsync(new NetworkMessage
97.                 {
98.                     Type = "Hello",
99.                     PlayerName = PlayerName,
100.                     RequestId = Guid.NewGuid().ToString("N")
101.                 });
102. 
103.                 return true;
104.             }
105.             catch (Exception ex)
106.             {
107.                 State = ConnectionState.Failed;
108.                 ErrorReceived?.Invoke(ex.Message);
109.                 Disconnect();
110.                 return false;
111.             }
112.         }
113. 
114.         public async Task SendAsync(NetworkMessage message)
115.         {
116.             if (_client == null || !_client.Connected || _stream == null)
117.             {
118.                 throw new InvalidOperationException("Chưa kết nối tới server TCP.");
119.             }
120. 
121.             var payload = Encoding.UTF8.GetBytes(JsonSerializer.Serialize(message, _jsonOptions));
122.             var lengthBuffer = BitConverter.GetBytes(payload.Length);
123.             var combined = new byte[lengthBuffer.Length + payload.Length];
124.             Buffer.BlockCopy(lengthBuffer, 0, combined, 0, lengthBuffer.Length);
125.             Buffer.BlockCopy(payload, 0, combined, lengthBuffer.Length, payload.Length);
126. 
127.             await _stream.WriteAsync(combined, 0, combined.Length);
128.             await _stream.FlushAsync();
129.         }
130. 
131.         private async Task ReceiveLoopAsync()
132.         {
133.             try
134.             {
135.                 while (_client != null && _client.Connected)
136.                 {
137.                     var message = await ReadMessageAsync();
138.                     if (message == null)
139.                     {
140.                         break;
141.                     }
142. 
143.                     _mainThreadActions.Enqueue(() => MessageReceived?.Invoke(message));
144.                 }
145.             }
146.             catch (Exception ex)
147.             {
148.                 _mainThreadActions.Enqueue(() => ErrorReceived?.Invoke(ex.Message));
149.             }
150.             finally
151.             {
152.                 var disconnectAction = new Action(() =>
153.                 {
154.                     State = ConnectionState.Disconnected;
155.                 });
156.                 _mainThreadActions.Enqueue(disconnectAction);
157.                 Disconnect();
158.             }
159.         }
160. 
161.         private async Task<NetworkMessage> ReadMessageAsync()
162.         {
163.             var lengthBuffer = new byte[4];
164.             var totalRead = 0;
165. 
166.             while (totalRead < 4)
167.             {
168.                 var read = await _stream.ReadAsync(lengthBuffer, totalRead, 4 - totalRead);
169.                 if (read == 0)
170.                 {
171.                     return null;
172.                 }
173. 
174.                 totalRead += read;
175.             }
176. 
177.             var payloadLength = BitConverter.ToInt32(lengthBuffer, 0);
178.             if (payloadLength <= 0 || payloadLength > 1_000_000)
179.             {
180.                 throw new InvalidOperationException("Payload length không hợp lệ.");
181.             }
182. 
183.             var payloadBuffer = new byte[payloadLength];
184.             var payloadRead = 0;
185.             while (payloadRead < payloadLength)
186.             {
187.                 var read = await _stream.ReadAsync(payloadBuffer, payloadRead, payloadLength - payloadRead);
188.                 if (read == 0)
189.                 {
190.                     return null;
191.                 }
192. 
193.                 payloadRead += read;
194.             }
195. 
196.             var json = Encoding.UTF8.GetString(payloadBuffer);
197.             return JsonSerializer.Deserialize<NetworkMessage>(json, _jsonOptions);
198.         }
199. 
200.         private void Update()
201.         {
202.             while (_mainThreadActions.TryDequeue(out var action))
203.             {
204.                 action?.Invoke();
205.             }
206.         }
207. 
208.         public void Disconnect()
209.         {
210.             if (_disposed)
211.             {
212.                 return;
213.             }
214. 
215.             _disposed = true;
216.             try
217.             {
218.                 _stream?.Close();
219.                 _client?.Close();
220.             }
221.             catch (ObjectDisposedException)
222.             {
223.             }
224. 
225.             _stream = null;
226.             _client = null;
227.             State = ConnectionState.Disconnected;
228.         }
229. 
230.         private void OnDestroy()
231.         {
232.             Disconnect();
233.         }
234.     }
235. }
