static GameObject CreateUIObject(string name, GameObject parent, Vector2 anchoredPos, Vector2 sizeDelta, Vector2 anchorMin, Vector2 anchorMax)
{
    var go = new GameObject(name);
    go.transform.SetParent(parent.transform, false);
    var rt = go.AddComponent<RectTransform>();
    rt.anchorMin = anchorMin;
    rt.anchorMax = anchorMax;
    rt.anchoredPosition = anchoredPos;
    rt.sizeDelta = sizeDelta;
    return go;
}

static void SetText(GameObject parent, string name, string text, int fontSize = 22, Color? color = null, TextAlignmentOptions alignment = TextAlignmentOptions.Left)
{
    var textObj = CreateUIObject(name, parent, Vector2.zero, new Vector2(300f, 40f), new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f));
    var tmp = textObj.AddComponent<TextMeshProUGUI>();
    tmp.text = text;
    tmp.fontSize = fontSize;
    tmp.alignment = alignment;
    tmp.color = color ?? new Color(1f, 1f, 1f, 1f);
    return;
}

static Button AddButton(GameObject parent, string name, string label, Vector2 anchoredPos, Vector2 sizeDelta, Color bgColor)
{
    var buttonObj = CreateUIObject(name, parent, anchoredPos, sizeDelta, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f));
    var image = buttonObj.AddComponent<Image>();
    image.color = bgColor;
    var button = buttonObj.AddComponent<Button>();
    var textObj = CreateUIObject("Text", buttonObj, Vector2.zero, new Vector2(0, 0), new Vector2(0, 0), new Vector2(1, 1));
    var text = textObj.AddComponent<TextMeshProUGUI>();
    text.text = label;
    text.alignment = TextAlignmentOptions.Center;
    text.fontSize = 24;
    text.color = Color.white;
    text.raycastTarget = false;
    var rect = textObj.GetComponent<RectTransform>();
    rect.anchorMin = Vector2.zero;
    rect.anchorMax = Vector2.one;
    rect.offsetMin = Vector2.zero;
    rect.offsetMax = Vector2.zero;
    var buttonText = buttonObj.GetComponentInChildren<TextMeshProUGUI>();
    button.transition = Selectable.Transition.ColorTint;
    return button;
}

static TMP_InputField AddInputField(GameObject parent, string name, Vector2 anchoredPos, Vector2 sizeDelta, string placeholderText)
{
    var fieldObj = CreateUIObject(name, parent, anchoredPos, sizeDelta, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f));
    var image = fieldObj.AddComponent<Image>();
    image.color = new Color(1f, 1f, 1f, 1f);
    var field = fieldObj.AddComponent<TMP_InputField>();
    var textArea = CreateUIObject("Text Area", fieldObj, Vector2.zero, new Vector2(0, 0), new Vector2(0, 0), new Vector2(1, 1));
    var textAreaRT = textArea.GetComponent<RectTransform>();
    textAreaRT.offsetMin = new Vector2(8f, 6f);
    textAreaRT.offsetMax = new Vector2(-8f, -6f);
    textArea.AddComponent<Mask>();
    var text = CreateUIObject("Text", textArea, Vector2.zero, new Vector2(0, 0), new Vector2(0, 0), new Vector2(1, 1));
    var textComponent = text.AddComponent<TextMeshProUGUI>();
    textComponent.text = "";
    textComponent.color = Color.black;
    textComponent.alignment = TextAlignmentOptions.Left;
    textComponent.raycastTarget = false;
    var placeholder = CreateUIObject("Placeholder", textArea, Vector2.zero, new Vector2(0, 0), new Vector2(0, 0), new Vector2(1, 1));
    var placeholderComponent = placeholder.AddComponent<TextMeshProUGUI>();
    placeholderComponent.text = placeholderText;
    placeholderComponent.color = new Color(0.55f, 0.55f, 0.55f, 1f);
    placeholderComponent.fontSize = 20;
    placeholderComponent.alignment = TextAlignmentOptions.Left;
    placeholderComponent.raycastTarget = false;
    field.textComponent = textComponent;
    field.placeholder = placeholderComponent;
    field.fontAsset = TMP_Settings.defaultFontAsset;
    return field;
}

static TMP_Dropdown AddDropdown(GameObject parent, string name, Vector2 anchoredPos, Vector2 sizeDelta)
{
    var obj = CreateUIObject(name, parent, anchoredPos, sizeDelta, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f));
    var image = obj.AddComponent<Image>();
    image.color = new Color(1f, 1f, 1f, 1f);
    var dropdown = obj.AddComponent<TMP_Dropdown>();
    dropdown.targetGraphic = image;
    var text = CreateUIObject("Text", obj, new Vector2(0f, 0f), new Vector2(0f, 0f), new Vector2(0f, 0f), new Vector2(1f, 1f));
    var textComp = text.AddComponent<TextMeshProUGUI>();
    textComp.text = "";
    textComp.alignment = TextAlignmentOptions.Left;
    textComp.fontSize = 18;
    textComp.color = Color.black;
    var arrow = CreateUIObject("Arrow", obj, new Vector2(0f, 0f), new Vector2(16f, 16f), new Vector2(1f, 0.5f), new Vector2(1f, 0.5f));
    var arrowImage = arrow.AddComponent<Image>();
    arrowImage.color = Color.gray;
    dropdown.template = null;
    return dropdown;
}

static Toggle AddToggle(GameObject parent, string name, Vector2 anchoredPos, Vector2 sizeDelta, string labelText)
{
    var obj = CreateUIObject(name, parent, anchoredPos, sizeDelta, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f));
