static Slider AddSlider(GameObject parent, string name, Vector2 anchoredPos, Vector2 sizeDelta, float min, float max)
{
    var obj = CreateUIObject(name, parent, anchoredPos, sizeDelta, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f));
