64.         public async Task<bool> ConnectAsync(string address, int port, string playerName)
65.         {
66.             if (State == ConnectionState.Connecting)
67.             {
68.                 return false;
69.             }
70. 
71.             if (string.IsNullOrWhiteSpace(address))
72.             {
73.                 address = "127.0.0.1";
74.             }
75. 
76.             State = ConnectionState.Connecting;
77.             ServerAddress = address;
78.             ServerPort = port;
79.             PlayerName = string.IsNullOrWhiteSpace(playerName) ? "Guest" : playerName;
80. 
81.             try
82.             {
83.                 _client = new TcpClient();
84.                 var timeoutTask = _client.ConnectAsync(address, port);
85.                 var completed = await Task.WhenAny(timeoutTask, Task.Delay(5000));
86.                 if (completed != timeoutTask)
87.                 {
88.                     throw new TimeoutException("Kết nối TCP quá thời gian chờ.");
89.                 }
90. 
91.                 await timeoutTask;
92.                 _stream = _client.GetStream();
93.                 State = ConnectionState.Connected;
94.                 _receiveLoopTask = Task.Run(ReceiveLoopAsync);
95. 
96.                 await SendAsync(new NetworkMessage
