49.     public enum ConnectionState
50.     {
51.         Disconnected,
52.         Connecting,
53.         Connected,
54.         Failed
55.     }
56. 
57.     public sealed class TcpGameClient : MonoBehaviour
58.     {
59.         private readonly ConcurrentQueue<Action> _mainThreadActions = new ConcurrentQueue<Action>();
60.         private readonly JsonSerializerOptions _jsonOptions = new JsonSerializerOptions
61.         {
62.             PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
63.             WriteIndented = false
64.         };
65. 
66.         private TcpClient _client;
67.         private NetworkStream _stream;
68.         private Task _receiveLoopTask;
69.         private bool _disposed;
70. 
71.         public ConnectionState State { get; private set; } = ConnectionState.Disconnected;
72.         public string ServerAddress { get; private set; } = "127.0.0.1";
73.         public int ServerPort { get; private set; } = 7777;
74.         public string PlayerName { get; private set; } = "Guest";
75. 
76.         public event Action<NetworkMessage> MessageReceived;
77.         public event Action<string> ErrorReceived;
78. 
79.         public bool IsConnected => _client != null && _client.Connected && State == ConnectionState.Connected;
80. 
81.         public async Task<bool> ConnectAsync(string address, int port, string playerName)
82.         {
83.             if (State == ConnectionState.Connecting)
84.             {
85.                 return false;
86.             }
87. 
88.             if (string.IsNullOrWhiteSpace(address))
89.             {
90.                 address = "127.0.0.1";
91.             }
92. 
93.             State = ConnectionState.Connecting;
94.             ServerAddress = address;
95.             ServerPort = port;
96.             PlayerName = string.IsNullOrWhiteSpace(playerName) ? "Guest" : playerName;
97. 
98.             try
99.             {
100.                 _client = new TcpClient();
101.                 var timeoutTask = _client.ConnectAsync(address, port);
102.                 var completed = await Task.WhenAny(timeoutTask, Task.Delay(5000));
103.                 if (completed != timeoutTask)
104.                 {
105.                     throw new TimeoutException("Kết nối TCP quá thời gian chờ.");
106.                 }
107. 
108.                 await timeoutTask;
109.                 _stream = _client.GetStream();
110.                 State = ConnectionState.Connected;
111.                 _receiveLoopTask = Task.Run(ReceiveLoopAsync);
112. 
113.                 await SendAsync(new NetworkMessage
114.                 {
115.                     Type = "Hello",
116.                     PlayerName = PlayerName,
117.                     RequestId = Guid.NewGuid().ToString("N")
118.                 });
119. 
120.                 return true;
121.             }
122.             catch (Exception ex)
123.             {
124.                 State = ConnectionState.Failed;
125.                 ErrorReceived?.Invoke(ex.Message);
126.                 Disconnect();
127.                 return false;
128.             }
129.         }
130. 
131.         public async Task SendAsync(NetworkMessage message)
132.         {
133.             if (_client == null || !_client.Connected || _stream == null)
134.             {
135.                 throw new InvalidOperationException("Chưa kết nối tới server TCP.");
136.             }
137. 
138.             var payload = Encoding.UTF8.GetBytes(JsonSerializer.Serialize(message, _jsonOptions));
139.             var lengthBuffer = BitConverter.GetBytes(payload.Length);
140.             var combined = new byte[lengthBuffer.Length + payload.Length];
141.             Buffer.BlockCopy(lengthBuffer, 0, combined, 0, lengthBuffer.Length);
142.             Buffer.BlockCopy(payload, 0, combined, lengthBuffer.Length, payload.Length);
143. 
144.             await _stream.WriteAsync(combined, 0, combined.Length);
145.             await _stream.FlushAsync();
146.         }
147. 
148.         private async Task ReceiveLoopAsync()
149.         {
150.             try
151.             {
152.                 while (_client != null && _client.Connected)
153.                 {
154.                     var message = await ReadMessageAsync();
155.                     if (message == null)
156.                     {
157.                         break;
158.                     }
159. 
160.                     _mainThreadActions.Enqueue(() => MessageReceived?.Invoke(message));
161.                 }
162.             }
163.             catch (Exception ex)
164.             {
165.                 _mainThreadActions.Enqueue(() => ErrorReceived?.Invoke(ex.Message));
166.             }
167.             finally
168.             {
169.                 var disconnectAction = new Action(() =>
170.                 {
171.                     State = ConnectionState.Disconnected;
172.                 });
173.                 _mainThreadActions.Enqueue(disconnectAction);
174.                 Disconnect();
175.             }
176.         }
177. 
178.         private async Task<NetworkMessage> ReadMessageAsync()
179.         {
180.             var lengthBuffer = new byte[4];
181.             var totalRead = 0;
182. 
183.             while (totalRead < 4)
184.             {
185.                 var read = await _stream.ReadAsync(lengthBuffer, totalRead, 4 - totalRead);
186.                 if (read == 0)
187.                 {
188.                     return null;
189.                 }
190. 
191.                 totalRead += read;
192.             }
193. 
194.             var payloadLength = BitConverter.ToInt32(lengthBuffer, 0);
195.             if (payloadLength <= 0 || payloadLength > 1_000_000)
196.             {
197.                 throw new InvalidOperationException("Payload length không hợp lệ.");
198.             }
199. 
200.             var payloadBuffer = new byte[payloadLength];
201.             var payloadRead = 0;
202.             while (payloadRead < payloadLength)
203.             {
204.                 var read = await _stream.ReadAsync(payloadBuffer, payloadRead, payloadLength - payloadRead);
205.                 if (read == 0)
206.                 {
207.                     return null;
208.                 }
209. 
210.                 payloadRead += read;
211.             }
212. 
213.             var json = Encoding.UTF8.GetString(payloadBuffer);
214.             return JsonSerializer.Deserialize<NetworkMessage>(json, _jsonOptions);
215.         }
216. 
217.         private void Update()
218.         {
219.             while (_mainThreadActions.TryDequeue(out var action))
220.             {
221.                 action?.Invoke();
222.             }
223.         }
224. 
225.         public void Disconnect()
226.         {
227.             if (_disposed)
228.             {
229.                 return;
230.             }
231. 
232.             _disposed = true;
233.             try
234.             {
235.                 _stream?.Close();
236.                 _client?.Close();
237.             }
238.             catch (ObjectDisposedException)
239.             {
240.             }
241. 
242.             _stream = null;
243.             _client = null;
244.             State = ConnectionState.Disconnected;
245.         }
246. 
247.         private void OnDestroy()
248.         {
249.             Disconnect();
250.         }
251.     }
252. }
