139.             var lengthBuffer = BitConverter.GetBytes(payload.Length);
140.             var combined = new byte[lengthBuffer.Length + payload.Length];
141.             Buffer.BlockCopy(lengthBuffer, 0, combined, 0, lengthBuffer.Length);
142.             Buffer.BlockCopy(payload, 0, combined, lengthBuffer.Length, payload.Length);
143. 
144.             await _stream.WriteAsync(combined, 0, combined.Length);
