266.             {
267.                 case "Welcome":
268.                     SetRoomStatus("Đã kết nối. Chọn một phòng để bắt đầu.");
269.                     break;
270.                 case "CreateRoomResult":
271.                     if (message.Success == true)
272.                     {
273.                         SetRoomStatus($"Phòng {message.RoomCode} đã được tạo.");
274.                     }
275.                     else
