78.     public sealed class TcpGameClient : MonoBehaviour
79.     {
80.         private readonly ConcurrentQueue<Action> _mainThreadActions = new ConcurrentQueue<Action>();
81.         private readonly JsonSerializerOptions _jsonOptions = new JsonSerializerOptions
82.         {
83.             PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
84.             WriteIndented = false
85.         };
86. 
87.         private TcpClient _client;
88.         private NetworkStream _stream;
89.         private Task _receiveLoopTask;
90.         private bool _disposed;
91. 
92.         public ConnectionState State { get; private set; } = ConnectionState.Disconnected;
93.         public string ServerAddress { get; private set; } = "127.0.0.1";
94.         public int ServerPort { get; private set; } = 7777;
95.         public string PlayerName { get; private set; } = "Guest";
96. 
97.         public event Action<NetworkMessage> MessageReceived;
98.         public event Action<string> ErrorReceived;
99. 
100.         public bool IsConnected => _client != null && _client.Connected && State == ConnectionState.Connected;
101. 
102.         public async Task<bool> ConnectAsync(string address, int port, string playerName)
103.         {
104.             if (State == ConnectionState.Connecting)
105.             {
106.                 return false;
107.             }
108. 
109.             if (string.IsNullOrWhiteSpace(address))
110.             {
111.                 address = "127.0.0.1";
112.             }
113. 
114.             State = ConnectionState.Connecting;
115.             ServerAddress = address;
116.             ServerPort = port;
117.             PlayerName = string.IsNullOrWhiteSpace(playerName) ? "Guest" : playerName;
118. 
119.             try
120.             {
121.                 _client = new TcpClient();
122.                 var timeoutTask = _client.ConnectAsync(address, port);
123.                 var completed = await Task.WhenAny(timeoutTask, Task.Delay(5000));
124.                 if (completed != timeoutTask)
125.                 {
126.                     throw new TimeoutException("Kết nối TCP quá thời gian chờ.");
127.                 }
128. 
129.                 await timeoutTask;
130.                 _stream = _client.GetStream();
131.                 State = ConnectionState.Connected;
132.                 _receiveLoopTask = Task.Run(ReceiveLoopAsync);
133. 
134.                 await SendAsync(new NetworkMessage
135.                 {
136.                     Type = "Hello",
137.                     PlayerName = PlayerName,
138.                     RequestId = Guid.NewGuid().ToString("N")
139.                 });
140. 
141.                 return true;
142.             }
143.             catch (Exception ex)
144.             {
145.                 State = ConnectionState.Failed;
146.                 ErrorReceived?.Invoke(ex.Message);
147.                 Disconnect();
148.                 return false;
149.             }
150.         }
151. 
152.         public async Task SendAsync(NetworkMessage message)
153.         {
154.             if (_client == null || !_client.Connected || _stream == null)
155.             {
156.                 throw new InvalidOperationException("Chưa kết nối tới server TCP.");
