78.     public sealed class TcpGameClient : MonoBehaviour
79.     {
80.         private readonly ConcurrentQueue<Action> _mainThreadActions = new ConcurrentQueue<Action>();
81.         private readonly JsonSerializerOptions _jsonOptions = new JsonSerializerOptions
82.         {
83.             PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
84.             WriteIndented = false
85.         };
86. 
87.         private TcpClient _client;
88.         private NetworkStream _stream;
89.         private Task _receiveLoopTask;
90.         private bool _disposed;
91. 
92.         public ConnectionState State { get; private set; } = ConnectionState.Disconnected;
93.         public string ServerAddress { get; private set; } = "127.0.0.1";
94.         public int ServerPort { get; private set; } = 7777;
95.         public string PlayerName { get; private set; } = "Guest";
96. 
97.         public event Action<NetworkMessage> MessageReceived;
98.         public event Action<string> ErrorReceived;
99. 
100.         public bool IsConnected => _client != null && _client.Connected && State == ConnectionState.Connected;
101. 
102.         public async Task<bool> ConnectAsync(string address, int port, string playerName)
103.         {
104.             if (State == ConnectionState.Connecting)
105.             {
106.                 return false;
107.             }
108. 
109.             if (string.IsNullOrWhiteSpace(address))
110.             {
111.                 address = "127.0.0.1";
112.             }
113. 
114.             State = ConnectionState.Connecting;
115.             ServerAddress = address;
116.             ServerPort = port;
117.             PlayerName = string.IsNullOrWhiteSpace(playerName) ? "Guest" : playerName;
118. 
119.             try
120.             {
121.                 _client = new TcpClient();
122.                 var timeoutTask = _client.ConnectAsync(address, port);
123.                 var completed = await Task.WhenAny(timeoutTask, Task.Delay(5000));
124.                 if (completed != timeoutTask)
125.                 {
126.                     throw new TimeoutException("Kết nối TCP quá thời gian chờ.");
127.                 }
128. 
129.                 await timeoutTask;
130.                 _stream = _client.GetStream();
131.                 State = ConnectionState.Connected;
132.                 _receiveLoopTask = Task.Run(ReceiveLoopAsync);
133. 
134.                 await SendAsync(new NetworkMessage
135.                 {
136.                     Type = "Hello",
137.                     PlayerName = PlayerName,
138.                     RequestId = Guid.NewGuid().ToString("N")
139.                 });
140. 
141.                 return true;
142.             }
143.             catch (Exception ex)
144.             {
145.                 State = ConnectionState.Failed;
146.                 ErrorReceived?.Invoke(ex.Message);
147.                 Disconnect();
148.                 return false;
149.             }
150.         }
151. 
152.         public async Task SendAsync(NetworkMessage message)
153.         {
154.             if (_client == null || !_client.Connected || _stream == null)
155.             {
156.                 throw new InvalidOperationException("Chưa kết nối tới server TCP.");
157.             }
158. 
159.             var payload = Encoding.UTF8.GetBytes(JsonSerializer.Serialize(message, _jsonOptions));
160.             var lengthBuffer = BitConverter.GetBytes(payload.Length);
161.             var combined = new byte[lengthBuffer.Length + payload.Length];
162.             Buffer.BlockCopy(lengthBuffer, 0, combined, 0, lengthBuffer.Length);
163.             Buffer.BlockCopy(payload, 0, combined, lengthBuffer.Length, payload.Length);
164. 
165.             await _stream.WriteAsync(combined, 0, combined.Length);
166.             await _stream.FlushAsync();
167.         }
168. 
169.         private async Task ReceiveLoopAsync()
170.         {
171.             try
172.             {
173.                 while (_client != null && _client.Connected)
174.                 {
175.                     var message = await ReadMessageAsync();
176.                     if (message == null)
177.                     {
178.                         break;
179.                     }
180. 
181.                     _mainThreadActions.Enqueue(() => MessageReceived?.Invoke(message));
182.                 }
183.             }
184.             catch (Exception ex)
185.             {
186.                 _mainThreadActions.Enqueue(() => ErrorReceived?.Invoke(ex.Message));
187.             }
188.             finally
189.             {
190.                 var disconnectAction = new Action(() =>
191.                 {
192.                     State = ConnectionState.Disconnected;
193.                 });
194.                 _mainThreadActions.Enqueue(disconnectAction);
195.                 Disconnect();
196.             }
197.         }
198. 
199.         private async Task<NetworkMessage> ReadMessageAsync()
200.         {
201.             var lengthBuffer = new byte[4];
202.             var totalRead = 0;
203. 
204.             while (totalRead < 4)
205.             {
206.                 var read = await _stream.ReadAsync(lengthBuffer, totalRead, 4 - totalRead);
207.                 if (read == 0)
208.                 {
209.                     return null;
210.                 }
211. 
212.                 totalRead += read;
213.             }
214. 
215.             var payloadLength = BitConverter.ToInt32(lengthBuffer, 0);
216.             if (payloadLength <= 0 || payloadLength > 1_000_000)
217.             {
218.                 throw new InvalidOperationException("Payload length không hợp lệ.");
219.             }
220. 
221.             var payloadBuffer = new byte[payloadLength];
222.             var payloadRead = 0;
223.             while (payloadRead < payloadLength)
224.             {
225.                 var read = await _stream.ReadAsync(payloadBuffer, payloadRead, payloadLength - payloadRead);
226.                 if (read == 0)
227.                 {
228.                     return null;
229.                 }
230. 
231.                 payloadRead += read;
232.             }
233. 
234.             var json = Encoding.UTF8.GetString(payloadBuffer);
235.             return JsonSerializer.Deserialize<NetworkMessage>(json, _jsonOptions);
236.         }
237. 
238.         private void Update()
239.         {
240.             while (_mainThreadActions.TryDequeue(out var action))
241.             {
242.                 action?.Invoke();
243.             }
244.         }
