123.         public async Task<bool> ConnectAsync(string address, int port, string playerName)
124.         {
125.             if (State == ConnectionState.Connecting)
126.             {
127.                 return false;
128.             }
129. 
130.             if (string.IsNullOrWhiteSpace(address))
131.             {
132.                 address = "127.0.0.1";
133.             }
134. 
135.             State = ConnectionState.Connecting;
136.             ServerAddress = address;
137.             ServerPort = port;
138.             PlayerName = string.IsNullOrWhiteSpace(playerName) ? "Guest" : playerName;
139. 
140.             try
141.             {
142.                 _client = new TcpClient();
143.                 var timeoutTask = _client.ConnectAsync(address, port);
144.                 var completed = await Task.WhenAny(timeoutTask, Task.Delay(5000));
145.                 if (completed != timeoutTask)
146.                 {
147.                     throw new TimeoutException("Kết nối TCP quá thời gian chờ.");
148.                 }
149. 
150.                 await timeoutTask;
151.                 _stream = _client.GetStream();
152.                 State = ConnectionState.Connected;
153.                 _receiveLoopTask = Task.Run(ReceiveLoopAsync);
154. 
155.                 await SendAsync(new NetworkMessage
156.                 {
157.                     Type = "Hello",
158.                     PlayerName = PlayerName,
159.                     RequestId = Guid.NewGuid().ToString("N")
160.                 });
161. 
162.                 return true;
163.             }
164.             catch (Exception ex)
165.             {
166.                 State = ConnectionState.Failed;
167.                 ErrorReceived?.Invoke(ex.Message);
168.                 Disconnect();
169.                 return false;
170.             }
171.         }
