173.         public async Task SendAsync(NetworkMessage message)
174.         {
175.             if (_client == null || !_client.Connected || _stream == null)
176.             {
177.                 throw new InvalidOperationException("Chưa kết nối tới server TCP.");
178.             }
179. 
180.             var payload = Encoding.UTF8.GetBytes(JsonSerializer.Serialize(message, _jsonOptions));
181.             var lengthBuffer = BitConverter.GetBytes(payload.Length);
182.             var combined = new byte[lengthBuffer.Length + payload.Length];
183.             Buffer.BlockCopy(lengthBuffer, 0, combined, 0, lengthBuffer.Length);
184.             Buffer.BlockCopy(payload, 0, combined, lengthBuffer.Length, payload.Length);
185. 
186.             await _stream.WriteAsync(combined, 0, combined.Length);
187.             await _stream.FlushAsync();
188.         }
