220.         private async Task<NetworkMessage> ReadMessageAsync()
221.         {
222.             var lengthBuffer = new byte[4];
223.             var totalRead = 0;
224. 
225.             while (totalRead < 4)
226.             {
227.                 var read = await _stream.ReadAsync(lengthBuffer, totalRead, 4 - totalRead);
228.                 if (read == 0)
229.                 {
230.                     return null;
231.                 }
232. 
233.                 totalRead += read;
234.             }
235. 
236.             var payloadLength = BitConverter.ToInt32(lengthBuffer, 0);
237.             if (payloadLength <= 0 || payloadLength > 1_000_000)
238.             {
239.                 throw new InvalidOperationException("Payload length không hợp lệ.");
240.             }
241. 
242.             var payloadBuffer = new byte[payloadLength];
243.             var payloadRead = 0;
244.             while (payloadRead < payloadLength)
245.             {
246.                 var read = await _stream.ReadAsync(payloadBuffer, payloadRead, payloadLength - payloadRead);
247.                 if (read == 0)
248.                 {
249.                     return null;
250.                 }
251. 
252.                 payloadRead += read;
253.             }
254. 
255.             var json = Encoding.UTF8.GetString(payloadBuffer);
256.             return JsonSerializer.Deserialize<NetworkMessage>(json, _jsonOptions);
257.         }
