99.     public sealed class TcpGameClient : MonoBehaviour
100.     {
101.         private readonly ConcurrentQueue<Action> _mainThreadActions = new ConcurrentQueue<Action>();
102.         private readonly JsonSerializerOptions _jsonOptions = new JsonSerializerOptions
103.         {
104.             PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
105.             WriteIndented = false
106.         };
107. 
108.         private TcpClient _client;
109.         private NetworkStream _stream;
110.         private Task _receiveLoopTask;
111.         private bool _disposed;
112. 
113.         public ConnectionState State { get; private set; } = ConnectionState.Disconnected;
114.         public string ServerAddress { get; private set; } = "127.0.0.1";
115.         public int ServerPort { get; private set; } = 7777;
116.         public string PlayerName { get; private set; } = "Guest";
117. 
118.         public event Action<NetworkMessage> MessageReceived;
119.         public event Action<string> ErrorReceived;
120. 
121.         public bool IsConnected => _client != null && _client.Connected && State == ConnectionState.Connected;
122. 
123.         public async Task<bool> ConnectAsync(string address, int port, string playerName)
124.         {
125.             if (State == ConnectionState.Connecting)
126.             {
127.                 return false;
128.             }
129. 
130.             if (string.IsNullOrWhiteSpace(address))
131.             {
132.                 address = "127.0.0.1";
133.             }
134. 
135.             State = ConnectionState.Connecting;
136.             ServerAddress = address;
137.             ServerPort = port;
138.             PlayerName = string.IsNullOrWhiteSpace(playerName) ? "Guest" : playerName;
139. 
140.             try
141.             {
142.                 _client = new TcpClient();
143.                 var timeoutTask = _client.ConnectAsync(address, port);
144.                 var completed = await Task.WhenAny(timeoutTask, Task.Delay(5000));
145.                 if (completed != timeoutTask)
146.                 {
147.                     throw new TimeoutException("Kết nối TCP quá thời gian chờ.");
148.                 }
149. 
150.                 await timeoutTask;
151.                 _stream = _client.GetStream();
152.                 State = ConnectionState.Connected;
153.                 _receiveLoopTask = Task.Run(ReceiveLoopAsync);
154. 
155.                 await SendAsync(new NetworkMessage
156.                 {
157.                     Type = "Hello",
158.                     PlayerName = PlayerName,
159.                     RequestId = Guid.NewGuid().ToString("N")
160.                 });
161. 
162.                 return true;
163.             }
164.             catch (Exception ex)
165.             {
166.                 State = ConnectionState.Failed;
167.                 ErrorReceived?.Invoke(ex.Message);
168.                 Disconnect();
169.                 return false;
170.             }
171.         }
172. 
173.         public async Task SendAsync(NetworkMessage message)
174.         {
175.             if (_client == null || !_client.Connected || _stream == null)
176.             {
177.                 throw new InvalidOperationException("Chưa kết nối tới server TCP.");
178.             }
179. 
180.             var payload = Encoding.UTF8.GetBytes(JsonSerializer.Serialize(message, _jsonOptions));
181.             var lengthBuffer = BitConverter.GetBytes(payload.Length);
182.             var combined = new byte[lengthBuffer.Length + payload.Length];
183.             Buffer.BlockCopy(lengthBuffer, 0, combined, 0, lengthBuffer.Length);
184.             Buffer.BlockCopy(payload, 0, combined, lengthBuffer.Length, payload.Length);
185. 
186.             await _stream.WriteAsync(combined, 0, combined.Length);
187.             await _stream.FlushAsync();
188.         }
189. 
190.         private async Task ReceiveLoopAsync()
191.         {
192.             try
193.             {
194.                 while (_client != null && _client.Connected)
195.                 {
196.                     var message = await ReadMessageAsync();
197.                     if (message == null)
198.                     {
199.                         break;
200.                     }
201. 
202.                     _mainThreadActions.Enqueue(() => MessageReceived?.Invoke(message));
203.                 }
204.             }
205.             catch (Exception ex)
206.             {
207.                 _mainThreadActions.Enqueue(() => ErrorReceived?.Invoke(ex.Message));
208.             }
209.             finally
210.             {
211.                 var disconnectAction = new Action(() =>
212.                 {
213.                     State = ConnectionState.Disconnected;
214.                 });
215.                 _mainThreadActions.Enqueue(disconnectAction);
216.                 Disconnect();
217.             }
218.         }
219. 
220.         private async Task<NetworkMessage> ReadMessageAsync()
221.         {
222.             var lengthBuffer = new byte[4];
223.             var totalRead = 0;
224. 
225.             while (totalRead < 4)
226.             {
227.                 var read = await _stream.ReadAsync(lengthBuffer, totalRead, 4 - totalRead);
228.                 if (read == 0)
229.                 {
230.                     return null;
231.                 }
232. 
233.                 totalRead += read;
234.             }
235. 
236.             var payloadLength = BitConverter.ToInt32(lengthBuffer, 0);
237.             if (payloadLength <= 0 || payloadLength > 1_000_000)
238.             {
239.                 throw new InvalidOperationException("Payload length không hợp lệ.");
240.             }
241. 
242.             var payloadBuffer = new byte[payloadLength];
243.             var payloadRead = 0;
244.             while (payloadRead < payloadLength)
245.             {
246.                 var read = await _stream.ReadAsync(payloadBuffer, payloadRead, payloadLength - payloadRead);
247.                 if (read == 0)
248.                 {
249.                     return null;
250.                 }
251. 
252.                 payloadRead += read;
253.             }
254. 
255.             var json = Encoding.UTF8.GetString(payloadBuffer);
256.             return JsonSerializer.Deserialize<NetworkMessage>(json, _jsonOptions);
257.         }
