{"script":"using System.Collections.Generic;
using System.Linq;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using ClassroomQuiz.UI;

var scenesDir = "Assets/Scenes";
if (!AssetDatabase.IsValidFolder(scenesDir))
{
    AssetDatabase.CreateFolder("Assets", "Scenes");
}

void EnsureBuildSettings(string scenePath)
{
    var scenes = EditorBuildSettings.scenes;
    if (scenes.Any(s => s.path == scenePath))
    {
        return;
    }

    var list = scenes.ToList();
    list.Add(new EditorBuildSettingsScene(scenePath, true));
    EditorBuildSettings.scenes = list.ToArray();
}

void SetRect(RectTransform rt, Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot, Vector2 sizeDelta, Vector2 anchoredPosition)
{
    rt.anchorMin = anchorMin;
    rt.anchorMax = anchorMax;
    rt.pivot = pivot;
    rt.sizeDelta = sizeDelta;
    rt.anchoredPosition = anchoredPosition;
}

TextMeshProUGUI CreateText(GameObject parent, string name, string text, Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot, Vector2 size, Vector2 anchoredPosition, int fontSize, Color color, TextAlignmentOptions align = TextAlignmentOptions.Center)
{
    var go = new GameObject(name, typeof(RectTransform));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, pivot, size, anchoredPosition);
    var tmp = go.AddComponent<TextMeshProUGUI>();
    tmp.text = text;
    tmp.fontSize = fontSize;
    tmp.color = color;
    tmp.alignment = align;
    tmp.raycastTarget = false;
    return tmp;
}

GameObject CreateButton(GameObject parent, string name, string text, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, Vector2? pivot = null)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(Button));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, pivot ?? new Vector2(0.5f, 0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = new Color(0.15f, 0.25f, 0.45f, 1f);
    var child = new GameObject("Text", typeof(RectTransform));
    child.transform.SetParent(go.transform, false);
    var childRT = child.GetComponent<RectTransform>();
    childRT.anchorMin = Vector2.zero;
    childRT.anchorMax = Vector2.one;
    childRT.offsetMin = Vector2.zero;
    childRT.offsetMax = Vector2.zero;
    var label = child.AddComponent<TextMeshProUGUI>();
    label.text = text;
    label.alignment = TextAlignmentOptions.Center;
    label.fontSize = 24;
    label.color = Color.white;
    label.raycastTarget = false;
    return go;
}

GameObject CreateInputField(GameObject parent, string name, string placeholder, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(TMP_InputField));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f, 0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = new Color(0.2f, 0.2f, 0.3f, 1f);
    var input = go.GetComponent<TMP_InputField>();
    var textArea = new GameObject("Text Area", typeof(RectTransform));
    textArea.transform.SetParent(go.transform, false);
    var areaRT = textArea.GetComponent<RectTransform>();
    areaRT.anchorMin = Vector2.zero;
    areaRT.anchorMax = Vector2.one;
    areaRT.offsetMin = new Vector2(8f, 6f);
    areaRT.offsetMax = new Vector2(-8f, -6f);
    var textGO = new GameObject("Text", typeof(RectTransform));
    textGO.transform.SetParent(textArea.transform, false);
    var textRT = textGO.GetComponent<RectTransform>();
    textRT.anchorMin = Vector2.zero;
    textRT.anchorMax = Vector2.one;
    textRT.offsetMin = Vector2.zero;
    textRT.offsetMax = Vector2.zero;
    var textComp = textGO.AddComponent<TextMeshProUGUI>();
    textComp.fontSize = 22;
    textComp.color = Color.white;
    textComp.raycastTarget = false;
    input.textComponent = textComp;
    input.textViewport = areaRT;
    var placeholderGO = new GameObject("Placeholder", typeof(RectTransform));
    placeholderGO.transform.SetParent(textArea.transform, false);
    var placeholderRT = placeholderGO.GetComponent<RectTransform>();
    placeholderRT.anchorMin = Vector2.zero;
    placeholderRT.anchorMax = Vector2.one;
    placeholderRT.offsetMin = new Vector2(5f, 0f);
    placeholderRT.offsetMax = new Vector2(-5f, 0f);
    var placeholderComp = placeholderGO.AddComponent<TextMeshProUGUI>();
    placeholderComp.text = placeholder;
    placeholderComp.fontSize = 20;
    placeholderComp.color = new Color(1f, 1f, 1f, 0.6f);
    placeholderComp.raycastTarget = false;
    input.placeholder = placeholderComp;
    return go;
}

GameObject CreateDropdown(GameObject parent, string name, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, List<string> options)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(TMP_Dropdown));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f, 0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = new Color(0.2f, 0.2f, 0.3f, 1f);
    var dropdown = go.GetComponent<TMP_Dropdown>();

    var labelGO = new GameObject("Label", typeof(RectTransform));
    labelGO.transform.SetParent(go.transform, false);
    var labelRT = labelGO.GetComponent<RectTransform>();
    labelRT.anchorMin = Vector2.zero;
    labelRT.anchorMax = Vector2.one;
    labelRT.offsetMin = new Vector2(8f, 0f);
    labelRT.offsetMax = new Vector2(-30f, 0f);
    var label = labelGO.AddComponent<TextMeshProUGUI>();
    label.fontSize = 20;
    label.color = Color.white;
    label.alignment = TextAlignmentOptions.Left;
    dropdown.captionText = label;
    dropdown.options = options.Select(o => new TMP_Dropdown.OptionData(o)).ToList();
    dropdown.value = 0;
    return go;
}

