{"script":"using System;
using System.Collections.Generic;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

var scenesDir = "Assets/Scenes";
if (!AssetDatabase.IsValidFolder(scenesDir))
{
    AssetDatabase.CreateFolder("Assets", "Scenes");
}

void EnsureBuildSettings(string scenePath)
{
    var scenes = EditorBuildSettings.scenes;
    if (scenes.Any(s => s.path == scenePath))
    {
        return;
    }

    var list = scenes.ToList();
    list.Add(new EditorBuildSettingsScene(scenePath, true));
    EditorBuildSettings.scenes = list.ToArray();
}

void SetRect(RectTransform rt, Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot, Vector2 sizeDelta, Vector2 anchoredPosition)
{
    rt.anchorMin = anchorMin;
    rt.anchorMax = anchorMax;
    rt.pivot = pivot;
    rt.sizeDelta = sizeDelta;
    rt.anchoredPosition = anchoredPosition;
}

Component AddTMProText(GameObject parent, string name, string text, Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot, Vector2 size, Vector2 anchoredPosition, int fontSize, Color color)
{
    var go = new GameObject(name, typeof(RectTransform));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, pivot, size, anchoredPosition);

    var tmpType = Type.GetType("TMPro.TextMeshProUGUI, Unity.TextMeshPro");
    if (tmpType != null)
    {
        var comp = go.AddComponent(tmpType);
        tmpType.GetProperty("text")?.SetValue(comp, text);
        tmpType.GetProperty("fontSize")?.SetValue(comp, fontSize);
        tmpType.GetProperty("color")?.SetValue(comp, color);
        var alignProp = tmpType.GetProperty("alignment");
        if (alignProp != null)
        {
            var alignmentValue = Enum.Parse(alignProp.PropertyType, "Center");
            alignProp.SetValue(comp, alignmentValue);
        }
        var raycastProp = tmpType.GetProperty("raycastTarget");
        if (raycastProp != null)
        {
            raycastProp.SetValue(comp, false);
        }
        return (Component)comp;
    }

    var uiText = go.AddComponent<Text>();
    uiText.text = text;
    uiText.fontSize = fontSize;
    uiText.color = color;
    uiText.alignment = TextAnchor.MiddleCenter;
    return uiText;
}

Component AddTMProInputField(GameObject parent, string name, string placeholderText, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f, 0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = new Color(0.18f, 0.18f, 0.24f, 1f);

    var tmpType = Type.GetType("TMPro.TMP_InputField, Unity.TextMeshPro");
    if (tmpType != null)
    {
        var comp = go.AddComponent(tmpType);
        var textArea = new GameObject("Text Area", typeof(RectTransform));
        textArea.transform.SetParent(go.transform, false);
        var areaRT = textArea.GetComponent<RectTransform>();
        areaRT.anchorMin = Vector2.zero;
        areaRT.anchorMax = Vector2.one;
        areaRT.offsetMin = new Vector2(8f, 6f);
        areaRT.offsetMax = new Vector2(-8f, -6f);

        var textGO = new GameObject("Text", typeof(RectTransform));
        textGO.transform.SetParent(textArea.transform, false);
        var textRT = textGO.GetComponent<RectTransform>();
        textRT.anchorMin = Vector2.zero;
        textRT.anchorMax = Vector2.one;
        textRT.offsetMin = Vector2.zero;
        textRT.offsetMax = Vector2.zero;
        var textComp = AddTMProText(textGO, "TextValue", "", Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, Vector2.zero, 22, Color.white);

        var placeholderGO = new GameObject("Placeholder", typeof(RectTransform));
        placeholderGO.transform.SetParent(textArea.transform, false);
        var placeholderRT = placeholderGO.GetComponent<RectTransform>();
        placeholderRT.anchorMin = Vector2.zero;
        placeholderRT.anchorMax = Vector2.one;
        placeholderRT.offsetMin = new Vector2(5f, 0f);
        placeholderRT.offsetMax = new Vector2(-5f, 0f);
        var placeholderComp = AddTMProText(placeholderGO, "PlaceholderValue", placeholderText, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, Vector2.zero, 20, new Color(1f, 1f, 1f, 0.6f));

        tmpType.GetProperty("textComponent")?.SetValue(comp, textComp);
        tmpType.GetProperty("placeholder")?.SetValue(comp, placeholderComp);
        tmpType.GetProperty("textViewport")?.SetValue(comp, areaRT);
        return comp;
    }

    var standard = go.AddComponent<InputField>();
    standard.text = "";
    return standard;
}

Component AddTMProDropdown(GameObject parent, string name, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, List<string> options)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f, 0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = new Color(0.2f, 0.2f, 0.3f, 1f);

    var dropdownType = Type.GetType("TMPro.TMP_Dropdown, Unity.TextMeshPro");
    if (dropdownType != null)
    {
        var dropdown = go.AddComponent(dropdownType);
        var label = new GameObject("Label", typeof(RectTransform));
        label.transform.SetParent(go.transform, false);
        var labelRT = label.GetComponent<RectTransform>();
        labelRT.anchorMin = Vector2.zero;
        labelRT.anchorMax = Vector2.one;
        labelRT.offsetMin = new Vector2(8f, 0f);
        labelRT.offsetMax = new Vector2(-30f, 0f);
        var labelText = AddTMProText(label, "LabelValue", options.FirstOrDefault() ?? "", Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, Vector2.zero, 20, Color.white);
        dropdownType.GetProperty("captionText")?.SetValue(dropdown, labelText);
        var optionDataList = typeof(List<>).MakeGenericType(Type.GetType("TMPro.TMP_Dropdown+OptionData, Unity.TextMeshPro"));
        var targetList = (System.Collections.IList)Activator.CreateInstance(optionDataList);
        foreach (var option in options)
        {
            var optionData = Activator.CreateInstance(Type.GetType("TMPro.TMP_Dropdown+OptionData, Unity.TextMeshPro"), option);
            targetList.Add(optionData);
        }
        dropdownType.GetProperty("options")?.SetValue(dropdown, targetList);
        dropdownType.GetProperty("value")?.SetValue(dropdown, 0);
        return dropdown;
    }

    var uiDropdown = go.AddComponent<Dropdown>();
    uiDropdown.options.Clear();
    foreach (var option in options)
    {
        uiDropdown.options.Add(new Dropdown.OptionData(option));
    }
    uiDropdown.value = 0;
    return uiDropdown;
}

