{"script":"using System.Collections.Generic;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using ClassroomQuiz.UI;

var loginPath = "Assets/Scenes/LoginScene.unity";
var startPath = "Assets/Scenes/StartScene.unity";
if (!AssetDatabase.IsValidFolder("Assets/Scenes")) AssetDatabase.CreateFolder("Assets", "Scenes");

void EnsureBuildSettings(string scenePath)
{
    var scenes = EditorBuildSettings.scenes;
    if (scenes.Any(s => s.path == scenePath)) return;
    var list = scenes.ToList();
    list.Add(new EditorBuildSettingsScene(scenePath, true));
    EditorBuildSettings.scenes = list.ToArray();
}

void SetRect(RectTransform rt, Vector2 aMin, Vector2 aMax, Vector2 pivot, Vector2 sizeDelta, Vector2 anchoredPosition)
{
    rt.anchorMin = aMin;
    rt.anchorMax = aMax;
    rt.pivot = pivot;
    rt.sizeDelta = sizeDelta;
    rt.anchoredPosition = anchoredPosition;
}

Text AddText(GameObject parent, string name, string textValue, Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot, Vector2 size, Vector2 anchoredPosition, int fontSize, TextAnchor alignment = TextAnchor.MiddleCenter, Color? color = null)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Text));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, pivot, size, anchoredPosition);
    var t = go.GetComponent<Text>();
    t.text = textValue;
    t.fontSize = fontSize;
    t.alignment = alignment;
    t.color = color ?? Color.white;
    t.font = Resources.GetBuiltinResource<Font>("Arial.ttf");
    return t;
}

Button AddButton(GameObject parent, string name, string label, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, Color? color = null)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(Button));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f, 0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = color ?? new Color(0.18f, 0.3f, 0.48f, 1f);
    var labelText = AddText(go, "Label", label, new Vector2(0f, 0f), new Vector2(1f, 1f), new Vector2(0.5f, 0.5f), new Vector2(0f, 0f), Vector2.zero, 22, TextAnchor.MiddleCenter, Color.white);
    var btn = go.GetComponent<Button>();
    btn.targetGraphic = go.GetComponent<Image>();
    return btn;
}

InputField AddInputField(GameObject parent, string name, string placeholder, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, bool isPassword = false)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(InputField));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f, 0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = new Color(0.18f, 0.18f, 0.24f, 1f);
    var input = go.GetComponent<InputField>();
    input.contentType = isPassword ? InputField.ContentType.Password : InputField.ContentType.Standard;
    var genericText = AddText(go, "Text", "", new Vector2(0f, 0f), new Vector2(1f, 1f), new Vector2(0.5f, 0.5f), new Vector2(0f, 0f), new Vector2(10f, 0f), 20, TextAnchor.MiddleLeft, Color.white);
    genericText.raycastTarget = false;
    input.textComponent = genericText;
    var placeholderText = AddText(go, "Placeholder", placeholder, new Vector2(0f, 0f), new Vector2(1f, 1f), new Vector2(0.5f, 0.5f), new Vector2(0f, 0f), new Vector2(10f, 0f), 20, TextAnchor.MiddleLeft, new Color(1f, 1f, 1f, 0.7f));
    placeholderText.raycastTarget = false;
    input.placeholder = placeholderText;
    return input;
}

Dropdown AddDropdown(GameObject parent, string name, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, List<string> options)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(Dropdown));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f, 0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = new Color(0.18f, 0.18f, 0.24f, 1f);
    var dd = go.GetComponent<Dropdown>();
    dd.options.Clear();
    foreach (var option in options) dd.options.Add(new Dropdown.OptionData(option));
    dd.value = 0;
    var caption = AddText(go, "Caption", options[0], new Vector2(0f, 0f), new Vector2(1f, 1f), new Vector2(0.5f, 0.5f), new Vector2(0f, 0f), Vector2.zero, 20, TextAnchor.MiddleCenter, Color.white);
    caption.raycastTarget = false;
    dd.captionText = caption;
    return dd;
}

Toggle AddToggle(GameObject parent, string name, string label, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, bool isOn = true)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Toggle));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f, 0.5f), size, anchoredPosition);
    var toggle = go.GetComponent<Toggle>();
    toggle.isOn = isOn;
    var bg = new GameObject("Background", typeof(RectTransform), typeof(Image));
    bg.transform.SetParent(go.transform, false);
    var bgRT = bg.GetComponent<RectTransform>();
    bgRT.anchorMin = new Vector2(0f, 0.5f); bgRT.anchorMax = new Vector2(0f, 0.5f); bgRT.sizeDelta = new Vector2(24f, 24f); bgRT.anchoredPosition = new Vector2(-60f, 0f);
    bg.GetComponent<Image>().color = Color.white;
    var check = new GameObject("Checkmark", typeof(RectTransform), typeof(Image));
    check.transform.SetParent(bg.transform, false);
    var checkRT = check.GetComponent<RectTransform>();
    checkRT.anchorMin = Vector2.zero; checkRT.anchorMax = Vector2.one; checkRT.offsetMin = Vector2.zero; checkRT.offsetMax = Vector2.zero;
    check.GetComponent<Image>().color = new Color(0.2f, 0.6f, 1f, 1f);
    toggle.graphic = check.GetComponent<Image>();
    AddText(go, "Label", label, new Vector2(0f, 0f), new Vector2(1f, 1f), new Vector2(0.5f, 0.5f), new Vector2(0f, 0f), new Vector2(18f, 0f), 18, TextAnchor.MiddleCenter, Color.white);
    return toggle;
}

Slider AddSlider(GameObject parent, string name, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, float value = 1f)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Slider));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f, 0.5f), size, anchoredPosition);
