attributes.gen_ai.tool.call.arguments:
{"script":"using System;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using ClassroomQuiz.UI;

var loginPath = "Assets/Scenes/LoginScene.unity";
var startPath = "Assets/Scenes/StartScene.unity";
if (!AssetDatabase.IsValidFolder("Assets/Scenes"))
{
    AssetDatabase.CreateFolder("Assets", "Scenes");
}

void SetRect(RectTransform rt, Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot, Vector2 sizeDelta, Vector2 anchoredPosition)
{
    rt.anchorMin = anchorMin;
    rt.anchorMax = anchorMax;
    rt.pivot = pivot;
    rt.sizeDelta = sizeDelta;
    rt.anchoredPosition = anchoredPosition;
}

Text MakeText(GameObject parent, string name, string value, Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot, Vector2 size, Vector2 anchoredPosition, int fontSize, Color color, TextAnchor alignment = TextAnchor.MiddleCenter)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Text));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, pivot, size, anchoredPosition);
    var text = go.GetComponent<Text>();
    text.text = value;
    text.font = Resources.GetBuiltinResource<Font>("Arial.ttf");
    text.fontSize = fontSize;
    text.color = color;
    text.alignment = alignment;
    return text;
}

Button MakeButton(GameObject parent, string name, string value, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(Button));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f, 0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = new Color(0.15f, 0.25f, 0.45f, 1f);
    var label = MakeText(go, "Label", value, new Vector2(0f,0f), new Vector2(1f,1f), new Vector2(0.5f,0.5f), new Vector2(0f,0f), Vector2.zero, 22, Color.white, TextAnchor.MiddleCenter);
    label.raycastTarget = false;
    var button = go.GetComponent<Button>();
    button.targetGraphic = go.GetComponent<Image>();
    return button;
}

InputField MakeInput(GameObject parent, string name, string placeholder, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, bool password = false)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(InputField));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f,0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = new Color(0.18f, 0.18f, 0.24f, 1f);
    var input = go.GetComponent<InputField>();
    input.contentType = password ? InputField.ContentType.Password : InputField.ContentType.Standard;
    var text = MakeText(go, "Text", string.Empty, new Vector2(0f,0f), new Vector2(1f,1f), new Vector2(0.5f,0.5f), new Vector2(0f,0f), new Vector2(10f,0f), 20, Color.white, TextAnchor.MiddleLeft);
    text.raycastTarget = false;
    input.textComponent = text;
    var placeholderText = MakeText(go, "Placeholder", placeholder, new Vector2(0f,0f), new Vector2(1f,1f), new Vector2(0.5f,0.5f), new Vector2(0f,0f), new Vector2(10f,0f), 20, new Color(1f,1f,1f,0.7f), TextAnchor.MiddleLeft);
    placeholderText.raycastTarget = false;
    input.placeholder = placeholderText;
    return input;
}

Dropdown MakeDropdown(GameObject parent, string name, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, params string[] options)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(Dropdown));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f,0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = new Color(0.18f, 0.18f, 0.24f, 1f);
    var dropdown = go.GetComponent<Dropdown>();
    dropdown.options.Clear();
    foreach (var option in options)
    {
        dropdown.options.Add(new Dropdown.OptionData(option));
    }
    dropdown.value = 0;
    var caption = MakeText(go, "Caption", options[0], new Vector2(0f,0f), new Vector2(1f,1f), new Vector2(0.5f,0.5f), new Vector2(0f,0f), Vector2.zero, 20, Color.white, TextAnchor.MiddleCenter);
    caption.raycastTarget = false;
    dropdown.captionText = caption;
    return dropdown;
}

Toggle MakeToggle(GameObject parent, string name, string label, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, bool isOn = true)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Toggle));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f,0.5f), size, anchoredPosition);
    var toggle = go.GetComponent<Toggle>();
    toggle.isOn = isOn;
