Slider MakeSlider(GameObject parent, string name, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, float value = 1f)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Slider));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f,0.5f), size, anchoredPosition);
    var slider = go.GetComponent<Slider>();
    slider.minValue = 0f; slider.maxValue = 1f; slider.value = value;
    var fillArea = new GameObject("Fill Area", typeof(RectTransform));
    fillArea.transform.SetParent(go.transform, false);
    var fillART = fillArea.GetComponent<RectTransform>();
    fillART.anchorMin = new Vector2(0f,0.5f); fillART.anchorMax = new Vector2(1f,0.5f); fillART.offsetMin = new Vector2(4f,-8f); fillART.offsetMax = new Vector2(-4f,8f);
    var fill = new GameObject("Fill", typeof(RectTransform), typeof(Image));
    fill.transform.SetParent(fillArea.transform, false);
    var fillRT = fill.GetComponent<RectTransform>();
    fillRT.anchorMin = Vector2.zero; fillRT.anchorMax = Vector2.one; fillRT.offsetMin = Vector2.zero; fillRT.offsetMax = Vector2.zero;
    fill.GetComponent<Image>().color = new Color(0.25f, 0.7f, 1f, 1f);
    slider.fillRect = fillRT;
    var handle = new GameObject("Handle", typeof(RectTransform), typeof(Image));
    handle.transform.SetParent(go.transform, false);
    var hRT = handle.GetComponent<RectTransform>();
    hRT.anchorMin = new Vector2(0.5f,0.5f); hRT.anchorMax = new Vector2(0.5f,0.5f); hRT.sizeDelta = new Vector2(18f,18f); hRT.anchoredPosition = Vector2.zero;
    handle.GetComponent<Image>().color = Color.white;
    slider.targetGraphic = handle.GetComponent<Image>();
    slider.handleRect = hRT;
    return slider;
}

