Dropdown MakeDropdown(GameObject parent, string name, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, params string[] options)
{
    var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(Dropdown));
    go.transform.SetParent(parent.transform, false);
    var rt = go.GetComponent<RectTransform>();
    SetRect(rt, anchorMin, anchorMax, new Vector2(0.5f,0.5f), size, anchoredPosition);
    go.GetComponent<Image>().color = new Color(0.18f, 0.18f, 0.24f, 1f);
    var dropdown = go.GetComponent<Dropdown>();
    dropdown.options.Clear();
    foreach (var option in options)
    {
        dropdown.options.Add(new Dropdown.OptionData(option));
    }
    dropdown.value = 0;
    var caption = MakeText(go, "Caption", options[0], new Vector2(0f,0f), new Vector2(1f,1f), new Vector2(0.5f,0.5f), new Vector2(0f,0f), Vector2.zero, 20, Color.white, TextAnchor.MiddleCenter);
    caption.raycastTarget = false;
    dropdown.captionText = caption;
    return dropdown;
}

Toggle MakeToggle(GameObject parent, string name, string label, Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Vector2 anchoredPosition, bool isOn = true)
