121.     public sealed class TcpGameClient : MonoBehaviour
122.     {
123.         private readonly ConcurrentQueue<Action> _mainThreadActions = new ConcurrentQueue<Action>();
124. 
125.         private TcpClient _client;
126.         private NetworkStream _stream;
127.         private Task _receiveLoopTask;
128.         private bool _disposed;
129. 
130.         public ConnectionState State { get; private set; } = ConnectionState.Disconnected;
131.         public string ServerAddress { get; private set; } = "127.0.0.1";
132.         public int ServerPort { get; private set; } = 7777;
133.         public string PlayerName { get; private set; } = "Guest";
134. 
135.         public event Action<NetworkMessage> MessageReceived;
136.         public event Action<string> ErrorReceived;
137. 
138.         public bool IsConnected => _client != null && _client.Connected && State == ConnectionState.Connected;
139. 
140.         public async Task<bool> ConnectAsync(string address, int port, string playerName)
141.         {
142.             if (State == ConnectionState.Connecting)
143.             {
144.                 return false;
145.             }
146. 
147.             if (string.IsNullOrWhiteSpace(address))
148.             {
149.                 address = "127.0.0.1";
150.             }
151. 
152.             State = ConnectionState.Connecting;
153.             ServerAddress = address;
154.             ServerPort = port;
155.             PlayerName = string.IsNullOrWhiteSpace(playerName) ? "Guest" : playerName;
156. 
157.             try
158.             {
159.                 _client = new TcpClient();
160.                 var timeoutTask = _client.ConnectAsync(address, port);
161.                 var completed = await Task.WhenAny(timeoutTask, Task.Delay(5000));
162.                 if (completed != timeoutTask)
163.                 {
164.                     throw new TimeoutException("Kết nối TCP quá thời gian chờ.");
165.                 }
166. 
167.                 await timeoutTask;
168.                 _stream = _client.GetStream();
169.                 State = ConnectionState.Connected;
170.                 _receiveLoopTask = Task.Run(ReceiveLoopAsync);
171. 
172.                 await SendAsync(new NetworkMessage
173.                 {
174.                     Type = "Hello",
175.                     PlayerName = PlayerName,
176.                     RequestId = Guid.NewGuid().ToString("N")
177.                 });
178. 
179.                 return true;
180.             }
181.             catch (Exception ex)
182.             {
183.                 State = ConnectionState.Failed;
184.                 ErrorReceived?.Invoke(ex.Message);
185.                 Disconnect();
186.                 return false;
187.             }
188.         }
189. 
190.         public async Task SendAsync(NetworkMessage message)
191.         {
192.             if (_client == null || !_client.Connected || _stream == null)
193.             {
194.                 throw new InvalidOperationException("Chưa kết nối tới server TCP.");
195.             }
196. 
197.             var json = NetworkMessageSerializer.Serialize(message);
198.             var payload = Encoding.UTF8.GetBytes(json);
199.             var lengthBuffer = BitConverter.GetBytes(payload.Length);
200.             var combined = new byte[lengthBuffer.Length + payload.Length];
201.             Buffer.BlockCopy(lengthBuffer, 0, combined, 0, lengthBuffer.Length);
202.             Buffer.BlockCopy(payload, 0, combined, lengthBuffer.Length, payload.Length);
203. 
204.             await _stream.WriteAsync(combined, 0, combined.Length);
205.             await _stream.FlushAsync();
206.         }
207. 
208.         private async Task ReceiveLoopAsync()
209.         {
210.             try
211.             {
212.                 while (_client != null && _client.Connected)
213.                 {
214.                     var message = await ReadMessageAsync();
215.                     if (message == null)
216.                     {
217.                         break;
218.                     }
219. 
220.                     _mainThreadActions.Enqueue(() => MessageReceived?.Invoke(message));
221.                 }
222.             }
223.             catch (Exception ex)
224.             {
225.                 _mainThreadActions.Enqueue(() => ErrorReceived?.Invoke(ex.Message));
226.             }
227.             finally
228.             {
229.                 var disconnectAction = new Action(() =>
230.                 {
231.                     State = ConnectionState.Disconnected;
232.                 });
233.                 _mainThreadActions.Enqueue(disconnectAction);
234.                 Disconnect();
235.             }
236.         }
