285.     private async Task HandleJoinRoomAsync(PlayerSession session, NetworkMessage message)
286.     {
287.         var roomCode = (message.RoomCode ?? string.Empty).Trim();
288.         if (string.IsNullOrWhiteSpace(roomCode))
289.         {
290.             await SendMessageAsync(session, new NetworkMessage
291.             {
292.                 Type = MessageTypes.JoinRoomResult,
293.                 RequestId = message.RequestId,
294.                 Success = false,
295.                 Error = "Mã phòng không hợp lệ."
296.             });
297.             return;
298.         }
299. 
300.         if (!_rooms.TryGetValue(roomCode, out var room))
301.         {
302.             await SendMessageAsync(session, new NetworkMessage
303.             {
304.                 Type = MessageTypes.JoinRoomResult,
305.                 RequestId = message.RequestId,
306.                 Success = false,
307.                 Error = "Mã phòng không tồn tại hoặc đã đóng."
308.             });
309.             return;
310.         }
311. 
312.         if (room.Players.Count >= room.Capacity)
313.         {
314.             await SendMessageAsync(session, new NetworkMessage
315.             {
316.                 Type = MessageTypes.JoinRoomResult,
317.                 RequestId = message.RequestId,
318.                 Success = false,
319.                 Error = "Phòng đã đầy."
320.             });
321.             return;
322.         }
323. 
324.         if (session.Room != null)
325.         {
326.             await HandleLeaveRoomAsync(session);
327.         }
328. 
329.         room.Players[session.PlayerId] = session;
330.         session.Room = room;
331.         session.Role = "Student";
332. 
333.         await BroadcastRoomStateAsync(room, MessageTypes.RoomStateUpdate, new
334.         {
335.             roomCode = room.RoomCode,
336.             role = session.Role,
337.             players = room.Players.Values.Select(p => new { playerId = p.PlayerId, displayname = p.DisplayName, role = p.Role }).ToArray(),
338.             count = room.Players.Count,
339.             capacity = room.Capacity,
340.             mode = room.Mode,
341.             lessonId = room.LessonId,
342.             durationSeconds = room.DurationSeconds
343.         });
344. 
345.         await SendMessageAsync(session, new NetworkMessage
346.         {
347.             Type = MessageTypes.JoinRoomResult,
348.             RequestId = message.RequestId,
349.             Success = true,
350.             RoomCode = room.RoomCode,
351.             Data = new { roomCode = room.RoomCode, role = session.Role }
352.         });
353.     }
354. 
355.     private async Task HandleLeaveRoomAsync(PlayerSession session)
356.     {
357.         if (session.Room == null)
358.         {
359.             return;
360.         }
361. 
362.         var room = session.Room;
363.         room.Players.TryRemove(session.PlayerId, out _);
364. 
365.         await BroadcastRoomStateAsync(room, MessageTypes.PlayerDisconnected, new
366.         {
367.             roomCode = room.RoomCode,
368.             playerId = session.PlayerId,
369.             displayName = session.DisplayName,
370.             remainingCount = room.Players.Count
371.         });
372. 
373.         if (room.Players.Count == 0)
374.         {
375.             _rooms.TryRemove(room.RoomCode, out _);
376.         }
377.         else
378.         {
379.             var newHost = room.Players.Values.FirstOrDefault();
380.             if (newHost != null && !string.Equals(room.HostPlayerId, newHost.PlayerId, StringComparison.Ordinal))
381.             {
382.                 room.HostPlayerId = newHost.PlayerId;
383.                 newHost.Role = "Teacher";
384.             }
385.         }
386. 
387.         session.Room = null;
388.         session.Role = "Student";
389.         session.HandRaised = false;
390.     }
391. 
392.     private async Task HandleStartGameAsync(PlayerSession session)
393.     {
394.         if (session.Room == null)
395.         {
396.             await SendMessageAsync(session, new NetworkMessage
397.             {
398.                 Type = MessageTypes.Error,
399.                 Error = "Bạn chưa ở trong phòng nào."
400.             });
401.             return;
402.         }
403. 
404.         var room = session.Room;
405.         if (!string.Equals(session.PlayerId, room.HostPlayerId, StringComparison.Ordinal))
406.         {
407.             await SendMessageAsync(session, new NetworkMessage
408.             {
409.                 Type = MessageTypes.Error,
410.                 Error = "Chỉ giáo viên mới bắt đầu trò chơi."
411.             });
412.             return;
413.         }
414. 
415.         room.Started = true;
416.         room.CurrentQuestionIndex = 0;
417.         await BroadcastRoomStateAsync(room, MessageTypes.StartCountdown, new
418.         {
419.             roomCode = room.RoomCode,
420.             startDelaySeconds = 3,
421.             lessonId = room.LessonId,
422.             mode = room.Mode
423.         });
424.         await SendMessageAsync(session, new NetworkMessage
425.         {
426.             Type = MessageTypes.StartCountdown,
427.             RoomCode = room.RoomCode,
428.             Success = true,
429.             Message = "Bài học đã bắt đầu. Đang chuẩn bị câu hỏi đầu tiên."
430.         });
431.     }
