469.     private Task SendMessageAsync(PlayerSession session, NetworkMessage message)
470.     {
471.         var payload = JsonSerializer.SerializeToUtf8Bytes(message, _jsonOptions);
472.         var header = BitConverter.GetBytes(payload.Length);
473.         var buffer = new byte[header.Length + payload.Length];
474.         Buffer.BlockCopy(header, 0, buffer, 0, header.Length);
475.         Buffer.BlockCopy(payload, 0, buffer, header.Length, payload.Length);
476. 
477.         return session.Stream.WriteAsync(buffer).AsTask();
478.     }
