85.     public sealed class JsonLessonRepository : IQuestionRepository
86.     {
87.         private readonly string _persistentPath;
88.         private readonly string _defaultDataPath;
89. 
90.         public JsonLessonRepository()
91.         {
92.             var baseDirectory = Path.Combine(Application.persistentDataPath, "ClassroomQuiz");
93.             Directory.CreateDirectory(baseDirectory);
94.             _persistentPath = Path.Combine(baseDirectory, "ClassroomQuizLessons.json");
95. 
96.             var streamingAssetsPath = Application.streamingAssetsPath;
97.             _defaultDataPath = string.IsNullOrEmpty(streamingAssetsPath)
98.                 ? Path.Combine(Application.dataPath, "StreamingAssets", "ClassroomQuizLessons.json")
99.                 : Path.Combine(streamingAssetsPath, "ClassroomQuizLessons.json");
100. 
101.             EnsureDefaultFileExists();
102.         }
103. 
104.         public List<LessonDefinition> LoadLessons()
105.         {
106.             var sourcePath = File.Exists(_persistentPath) ? _persistentPath : _defaultDataPath;
107.             if (!File.Exists(sourcePath))
108.             {
109.                 return BuildDefaultLessons();
110.             }
111. 
112.             try
113.             {
114.                 var json = File.ReadAllText(sourcePath);
115.                 var data = JsonUtility.FromJson<LessonRepositoryData>(json);
116.                 if (data == null || data.lessons == null || data.lessons.Count == 0)
117.                 {
118.                     return BuildDefaultLessons();
119.                 }
120. 
121.                 return data.lessons;
122.             }
123.             catch (Exception)
124.             {
125.                 return BuildDefaultLessons();
126.             }
127.         }
128. 
129.         public LessonDefinition GetLesson(int lessonId)
130.         {
131.             var lessons = LoadLessons();
132.             foreach (var lesson in lessons)
133.             {
134.                 if (lesson.lessonId == lessonId)
135.                 {
136.                     return lesson;
137.                 }
138.             }
139. 
140.             return lessons.Count > 0 ? lessons[0] : new LessonDefinition();
141.         }
142. 
143.         public bool SaveLessons(List<LessonDefinition> lessons)
144.         {
145.             try
146.             {
147.                 var repositoryData = new LessonRepositoryData { lessons = lessons };
148.                 var json = JsonUtility.ToJson(repositoryData, true);
149.                 File.WriteAllText(_persistentPath, json);
150.                 return true;
151.             }
152.             catch (Exception)
153.             {
154.                 return false;
155.             }
156.         }
157. 
158.         public static List<LessonDefinition> BuildDefaultLessons()
159.         {
160.             var lessons = new List<LessonDefinition>();
161.             for (var i = 1; i <= 42; i++)
162.             {
163.                 var lesson = new LessonDefinition
164.                 {
165.                     lessonId = i,
166.                     title = $"Bài {i}",
167.                     status = LessonStatus.Draft,
168.                     isDemo = false,
169.                     summary = "Đang chờ giáo viên chỉnh sửa câu hỏi.",
170.                     defaultQuestionDurationSeconds = 15,
171.                     questions = new List<LessonQuestionData>()
172.                 };
173. 
174.                 if (i == 1)
175.                 {
176.                     lesson.title = "Bài 1 (Demo)";
177.                     lesson.status = LessonStatus.Ready;
178.                     lesson.isDemo = true;
179.                     lesson.summary = "Demo — đề mẫu, cần giáo viên rà soát lại trước khi dùng chính thức.";
180.                     lesson.questions = new List<LessonQuestionData>
181.                     {
182.                         new LessonQuestionData
183.                         {
184.                             questionId = "demo-1",
185.                             sequenceIndex = 1,
186.                             prompt = "Diện tích của một tam giác có đáy 12 cm và chiều cao 8 cm là bao nhiêu?",
187.                             options = new List<string> { "48 cm²", "64 cm²", "96 cm²", "72 cm²" },
188.                             correctIndex = 2,
189.                             explanation = "Diện tích tam giác = (đáy × chiều cao) / 2 = (12 × 8) / 2 = 48 cm²."
190.                         },
191.                         new LessonQuestionData
192.                         {
193.                             questionId = "demo-2",
194.                             sequenceIndex = 2,
195.                             prompt = "Nếu tăng đáy lên gấp đôi nhưng giữ nguyên chiều cao, diện tích tam giác mới sẽ thay đổi như thế nào?",
196.                             options = new List<string> { "Giảm đi một nửa", "Không đổi", "Tăng gấp đôi", "Tăng gấp bốn" },
197.                             correctIndex = 2,
198.                             explanation = "Diện tích tam giác tỉ lệ thuận với đáy, nên nếu đáy tăng gấp đôi thì diện tích cũng tăng gấp đôi."
199.                         },
200.                         new LessonQuestionData
201.                         {
202.                             questionId = "demo-3",
203.                             sequenceIndex = 3,
204.                             prompt = "Công thức tính diện tích tam giác là gì?",
205.                             options = new List<string> { "a × b", "(a × h) / 2", "a + b + c", "(a + b) / 2" },
206.                             correctIndex = 1,
207.                             explanation = "Công thức tính diện tích tam giác là (đáy × chiều cao) / 2."
208.                         }
209.                     };
210.                 }
211. 
212.                 lessons.Add(lesson);
213.             }
214. 
215.             return lessons;
216.         }
217. 
218.         private void EnsureDefaultFileExists()
219.         {
220.             if (!File.Exists(_defaultDataPath))
221.             {
222.                 var directory = Path.GetDirectoryName(_defaultDataPath);
223.                 if (!string.IsNullOrEmpty(directory))
224.                 {
225.                     Directory.CreateDirectory(directory);
226.                 }
227. 
228.                 var data = new LessonRepositoryData { lessons = BuildDefaultLessons() };
229.                 var json = JsonUtility.ToJson(data, true);
230.                 File.WriteAllText(_defaultDataPath, json);
231.             }
232.         }
233.     }
