        if (comp == null) continue;
        Debug.Log(pad + "  CMP " + comp.GetType().Name);
    }
    for (int i=0;i<go.transform.childCount;i++)
    {
        Dump(go.transform.GetChild(i).gameObject, depth + 1);
    }
}
"}

