14.     [Serializable]
15.     public class LessonQuestionData
16.     {
17.         public string questionId = "";
18.         public int sequenceIndex;
19.         public string prompt = "";
20.         public List<string> options = new List<string> { "", "", "", "" };
21.         public int correctIndex;
