107.             if (!File.Exists(sourcePath))
108.             {
109.                 return BuildDefaultLessons();
110.             }
111. 
112.             try
113.             {
114.                 var json = File.ReadAllText(sourcePath);
115.                 var data = JsonUtility.FromJson<LessonRepositoryData>(json);
116.                 if (data == null || data.lessons == null || data.lessons.Count == 0)
117.                 {
118.                     return BuildDefaultLessons();
119.                 }
120. 
121.                 return data.lessons;
122.             }
123.             catch (Exception)
124.             {
125.                 return BuildDefaultLessons();
126.             }
