GameObject EnsureChild(GameObject parent, string name)
{
    var child = parent.transform.Find(name);
    if (child != null) return child.gameObject;
    var go = new GameObject(name);
    go.transform.SetParent(parent.transform, false);
    return go;
}

GameObject EnsurePanel(GameObject parent, string name, Vector2 anchoredPosition, Vector2 sizeDelta, Color color)
{
    var panel = EnsureChild(parent, name);
    panel.transform.localPosition = anchoredPosition;
    var rect = panel.GetComponent<RectTransform>();
    if (rect == null) rect = panel.AddComponent<RectTransform>();
    rect.anchorMin = new Vector2(0.5f, 0.5f);
    rect.anchorMax = new Vector2(0.5f, 0.5f);
    rect.sizeDelta = sizeDelta;
    rect.localScale = Vector3.one;
    rect.anchoredPosition = anchoredPosition;
    var image = panel.GetComponent<Image>();
    if (image == null) image = panel.AddComponent<Image>();
    image.color = color;
    if (panel.transform.parent == null)
    {
        panel.transform.SetParent(parent.transform, false);
