void EnsureSceneSetup(string scenePath, Scene scene)
{
    var root = scene.GetRootGameObjects();
    var canvasGo = root.FirstOrDefault(go => go.name == "Canvas") ?? new GameObject("Canvas");
    canvasGo.transform.SetParent(null, false);
    var canvas = canvasGo.GetComponent<Canvas>();
    if (canvas == null) canvas = canvasGo.AddComponent<Canvas>();
    canvas.renderMode = RenderMode.ScreenSpaceOverlay;
    var scaler = canvasGo.GetComponent<CanvasScaler>();
    if (scaler == null) scaler = canvasGo.AddComponent<CanvasScaler>();
    scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
    scaler.referenceResolution = new Vector2(1920f, 1080f);
    scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
    scaler.matchWidthOrHeight = 0.5f;
    var raycaster = canvasGo.GetComponent<GraphicRaycaster>();
    if (raycaster == null) canvasGo.AddComponent<GraphicRaycaster>();

    var eventSystem = root.FirstOrDefault(go => go.name == "EventSystem") ?? new GameObject("EventSystem");
    if (eventSystem.GetComponent<EventSystem>() == null) eventSystem.AddComponent<EventSystem>();
    if (eventSystem.GetComponent<StandaloneInputModule>() == null) eventSystem.AddComponent<StandaloneInputModule>();

    if (scenePath.EndsWith("LoginScene.unity"))
    {
        SetupLoginScene(canvasGo);
    }
    else if (scenePath.EndsWith("StartScene.unity"))
    {
        SetupStartScene(canvasGo);
    }
}

