25.     [Serializable]
26.     public class LessonDefinition
27.     {
28.         public int lessonId;
29.         public string title = "";
30.         public LessonStatus status;
31.         public bool isDemo;
32.         public string summary = "";
33.         public int defaultQuestionDurationSeconds = 15;
34.         public List<LessonQuestionData> questions = new List<LessonQuestionData>();
35. 
36.         public bool IsReadyForRoom => status == LessonStatus.Ready && questions != null && questions.Count >= 2 && questions.Count <= 5 && ValidateQuestions();
37. 
38.         public bool ValidateQuestions()
39.         {
40.             if (questions == null || questions.Count < 2 || questions.Count > 5)
41.             {
42.                 return false;
43.             }
44. 
45.             foreach (var question in questions)
46.             {
47.                 if (string.IsNullOrWhiteSpace(question.prompt))
48.                 {
49.                     return false;
50.                 }
51. 
52.                 if (question.options == null || question.options.Count != 4)
53.                 {
54.                     return false;
55.                 }
56. 
57.                 if (question.options.Exists(string.IsNullOrWhiteSpace))
58.                 {
59.                     return false;
60.                 }
61. 
62.                 if (question.correctIndex < 0 || question.correctIndex > 3)
63.                 {
64.                     return false;
65.                 }
66.             }
67. 
68.             return true;
69.         }
70.     }
